SDL.tradicoesInfo=[{"nome": "Adivinhação", "atr": "intelecto", "trevas": false}, {"nome": "Alteração", "atr": "vontade", "trevas": false}, {"nome": "Ar", "atr": "vontade", "trevas": false}, {"nome": "Arcana", "atr": "intelecto", "trevas": false}, {"nome": "Batalha", "atr": "intelecto", "trevas": false}, {"nome": "Canção", "atr": "vontade", "trevas": false}, {"nome": "Caos", "atr": "vontade", "trevas": false}, {"nome": "Celestial", "atr": "vontade", "trevas": false}, {"nome": "Conjuração", "atr": "intelecto", "trevas": false}, {"nome": "Destruição", "atr": "vontade", "trevas": false}, {"nome": "Encantamento", "atr": "intelecto", "trevas": false}, {"nome": "Fogo", "atr": "vontade", "trevas": false}, {"nome": "Ilusão", "atr": "intelecto", "trevas": false}, {"nome": "Maldição", "atr": "intelecto", "trevas": true}, {"nome": "Natureza", "atr": "vontade", "trevas": false}, {"nome": "Necromancia", "atr": "intelecto", "trevas": true}, {"nome": "Primal", "atr": "vontade", "trevas": false}, {"nome": "Proibida", "atr": "intelecto", "trevas": true}, {"nome": "Proteção", "atr": "intelecto", "trevas": false}, {"nome": "Runas", "atr": "intelecto", "trevas": false}, {"nome": "Sombras", "atr": "intelecto", "trevas": false}, {"nome": "Tecnomancia", "atr": "intelecto", "trevas": false}, {"nome": "Teletransporte", "atr": "intelecto", "trevas": false}, {"nome": "Tempestade", "atr": "vontade", "trevas": false}, {"nome": "Tempo", "atr": "intelecto", "trevas": false}, {"nome": "Terra", "atr": "vontade", "trevas": false}, {"nome": "Teurgia", "atr": "vontade", "trevas": false}, {"nome": "Transformação", "atr": "vontade", "trevas": false}, {"nome": "Vida", "atr": "vontade", "trevas": false}, {"nome": "Água", "atr": "vontade", "trevas": false}];
SDL.feiticos=[{"id":"adivinhacao-bisbilhotar","nome":"Bisbilhotar","tipo":"Utilitário","trad":"Adivinhação","grau":0,"texto":"Duração: Concentração, até 1 minuto Escolha um ponto no espaço a longa distância dentro de seu campo de visão. Pela duração do feitiço, você escuta tudo como se estivesse no ponto escolhido."},{"id":"adivinhacao-epifania","nome":"Epifania","tipo":"Utilitário","trad":"Adivinhação","grau":0,"texto":"Desencadeada: Você usa uma ação desencadeada para conjurar este feitiço quando faz uma rolagem de desafio ou de ataque. Você rola o d20 duas vezes e usa o maior valor obtido nos dados."},{"id":"adivinhacao-augurio","nome":"Augúrio","tipo":"Utilitário","trad":"Adivinhação","grau":1,"texto":"Requisito: Você deve usar implementos de adivinhação, como cartas, dados, folhas de chá ou varetas marcadas. Duração: Concentração, até 1 minuto Enquanto se concentra, você utiliza suas ferramentas de adivinhação para obter uma visão do futuro. Ao final desse período, faça ao MJ uma pergunta que pode ser respondida com “sim” ou “não”. O MJ deve responder à pergunta com sinceridade."},{"id":"adivinhacao-predizer","nome":"Predizer","tipo":"Utilitário","trad":"Adivinhação","grau":1,"texto":"Alvo: Uma criatura a curta distância em seu campo de visão Duração: Concentração, até 1 minuto Enquanto o efeito durar, sempre o alvo faz uma rolagem de ataque ou de desafio e pode ouvi-lo, ele faz a rolagem com 3 dádivas."},{"id":"adivinhacao-psicometria","nome":"Psicometria","tipo":"Utilitário","trad":"Adivinhação","grau":1,"texto":"Alvo: Um objeto ao seu alcance Ao tocar no alvo, você descobre 1d6 fatos a respeito dele, como: a identidade de seu dono anterior; se o objeto é amaldiçoado, possuído ou mágico; como um dono anterior obteve ou perdeu esse objeto; e onde ele foi feito."},{"id":"adivinhacao-ouvido-franco","nome":"Ouvido Franco","tipo":"Utilitário","trad":"Adivinhação","grau":2,"texto":"Duração: 1 hora Enquanto o efeito durar, você compreende todas as línguas faladas que pode ouvir e reconhece a verdade quando a ouve."},{"id":"adivinhacao-quiromancia","nome":"Quiromancia","tipo":"Utilitário","trad":"Adivinhação","grau":2,"texto":"Alvo: Uma criatura ao seu alcance Duração: Concentração, até 1 minuto Enquanto você se concentra, você lê a palma da mão do alvo. Quando o feitiço terminar, você revela pistas sobre o futuro do alvo. O alvo ganha seis percepções, as quais retém por 1 hora ou até gastar a última delas. Ao fazer uma rolagem de ataque ou de desafio, ele pode gastar uma percepção para fazer a rolagem com 2 dádivas."},{"id":"adivinhacao-localizar","nome":"Localizar","tipo":"Utilitário","trad":"Adivinhação","grau":3,"texto":"Duração: 1 hora; veja o efeito Você deve se concentrar por 1 minuto, visualizando uma criatura ou um objeto em sua mente. Você pode visualizar algo específico, como o cálice do qual o monarca bebeu pela última vez, ou uma categoria mais ampla, como uma armadilha. Ao terminar sua visualização mental, pela duração do feitiço você saberá a localização da criatura ou do objeto escolhido sempre que estiver a média distância dele. É impossível esconder o alvo de você durante esse período. Esse conhecimento também revela o caminho que você precisa seguir para chegar à criatura ou ao objeto. Se houver mais de um alvo com mesma descrição, você saberá a localização de cada um deles."},{"id":"adivinhacao-ver-o-futuro","nome":"Ver o Futuro","tipo":"Utilitário","trad":"Adivinhação","grau":3,"texto":"Duração: 1 minuto Enquanto o efeito durar, você recebe os seguintes benefícios: seu movimento não desencadeia ataques livres; você impõe 2 reveses nas rolagens de ataque feitas contra você; e faz rolagens de desafio de Agilidade com 2 dádivas para resistir a ataques e outros efeitos nocivos."},{"id":"adivinhacao-visao","nome":"Visão","tipo":"Utilitário","trad":"Adivinhação","grau":4,"texto":"Duração: 1 hora; veja o efeito Enquanto o efeito durar, você obtém os seguintes benefícios: • Você enxerga áreas obscurecidas por sombras como se essas áreas estivessem iluminadas. • Você enxerga através de tudo que esconde, disfarça ou torna coisas invisíveis. • Você vê auras ao redor de objetos afetados por magia e reconhece automaticamente qualquer coisa criada por um feitiço de Ilusão como tal. • Você vê a aparência real de criaturas afetadas por feitiços de Transformação. • Você pode usar uma ação para direcionar sua visão e enxergar através de obstáculos sólidos enquanto estiver se concentrando. É possível enxergar através de 1 metro de madeira, 30 centímetros de pedra ou 2,5 centímetros de metal."},{"id":"adivinhacao-clarividencia","nome":"Clarividência","tipo":"Utilitário","trad":"Adivinhação","grau":5,"texto":"Alvo: Uma bola de cristal ao seu alcance Duração: Concentração, até 1 hora; veja o efeito Você toca o alvo e se concentra por 1 minuto. Durante esse tempo, visualiza um lugar que já tenha visto ao menos uma vez. O local deve caber dentro de um cubo de aproximadamente 10 metros de lado e estar a até 1,5 quilômetro de você. Ao final desse período, a bola de cristal se enche de névoa, que então se dissipa, revelando o lugar visualizado em sua mente. A bola de cristal mostra esse local a todos que possam vê-la pela duração do feitiço."},{"id":"agua-congelar","nome":"Congelar","tipo":"Ataque","trad":"Água","grau":0,"texto":"Alvo: Uma criatura viva a curta distância A temperatura cai drasticamente ao redor do alvo. Faça uma rolagem de ataque de Vontade contra a Agilidade do alvo. Em caso de sucesso, o alvo sofre 1d3 de dano e fica imobilizado por 1 rodada. Rolagem de Ataque 20+ O alvo sofre 1d3 de dano extra."},{"id":"agua-produzir-agua","nome":"Produzir Água","tipo":"Utilitário","trad":"Água","grau":0,"texto":"Alvo: Um cálice, tigela ou recipiente similar ao seu alcance Você toca o alvo, que se enche de água fresca e limpa."},{"id":"agua-afogar","nome":"Afogar","tipo":"Ataque","trad":"Água","grau":1,"texto":"Alvo: Uma criatura a curta distância que respira ar Água se acumula nos pulmões da vítima ou em um órgão semelhante. O alvo deve fazer uma rolagem de desafio de Força; se fracassar, sofre 1d6+2 de dano e fica debilitado. Ao final de cada rodada em que o alvo esteja debilitado dessa maneira, ele deve fazer uma rolagem de desafio de Força com 1 revés; em caso de sucesso, essa aflição é removida. Após três fracassos, o alvo sufoca e morre afogado."},{"id":"agua-explosao-de-gelo","nome":"Explosão de Gelo","tipo":"Ataque","trad":"Água","grau":1,"texto":"Área: Um cone, com 3 metros de comprimento, com origem em um ponto ao seu alcance Você arremessa estilhaços de gelo serrilhados que causam 2d6+2 de dano em tudo que estiver na área — ou metade desse dano com um sucesso em uma rolagem de desafio de Agilidade. O terreno na área conta como difícil por 1 rodada."},{"id":"agua-manancial-da-vida","nome":"Manancial da Vida","tipo":"Utilitário","trad":"Água","grau":1,"texto":"Área: Um hemisfério com raio de 2 metros centralizado em um ponto no chão a curta distância Duração: 1 minuto As águas curativas obscurecem parcialmente a área pela duração do feitiço. Cada criatura viva dentro da área não precisa beber água até completar um descanso. Além disso, quando uma criatura na área cura dano, ela também cura 1d3 dano extra."},{"id":"agua-geiser","nome":"Gêiser","tipo":"Ataque","trad":"Água","grau":2,"texto":"Área: Um círculo com raio de 5 metros centralizado em um ponto a média distância Uma coluna de água escaldante irrompe na área, alcançando 2d6 metros de altura antes de cair no chão estendendose por metade dessa distância além da área e extinguindo chamas desprotegidas. A força da água move objetos soltos de Tamanho 1 ou menores por 1d6 metros a partir do ponto de origem, enquanto cada criatura na área sofre 2d6+2 de dano da água escaldante e deve fazer uma rolagem de desafio de Agilidade. Se fracassar, a criatura fica prostrada; em caso de sucesso, sofre apenas metade do dano."},{"id":"agua-onda","nome":"Onda","tipo":"Ataque","trad":"Água","grau":2,"texto":"Área: Uma linha com 10 metros de comprimento e 1 metro de largura, com origem em um ponto no chão a média distância Duração: 1 minuto Uma onda de água surge na área pela duração do feitiço. A água proporciona obscurecimento parcial a tudo o que estiver em seu espaço ou atrás dela, além de oferecer meia cobertura. A água também extingue quaisquer chamas na área. Quando o efeito termina, a linha de água inclina-se e cai para longe de você ou em sua direção, conforme você escolher, cobrindo uma área de 10 metros de comprimento por 10 metros de largura. Cada criatura nessa área sofre 1d6 de dano e deve fazer uma rolagem de desafio de Força. Se fracassar, ela fica prostrada; em caso de sucesso, sofre apenas metade do dano. A água então se espalha por mais 10 metros em todas as direções, extinguindo quaisquer chamas que tocar."},{"id":"agua-esfera-de-agua","nome":"Esfera de Água","tipo":"Ataque","trad":"Água","grau":3,"texto":"Área: Uma esfera com raio de 3 metros centralizada em um ponto a média distância Duração: Concentração, até 1 minuto Toda a área é preenchida com água pela duração do feitiço. Cada vez que usar uma ação para se concentrar no feitiço, você pode mover a esfera e tudo o que estiver dentro dela por até 5 metros em qualquer direção. Cada criatura que estiver na área quando você conjura o feitiço fica presa na esfera, assim como qualquer criatura que estiver em um espaço que a esfera entrar. Ao final de cada rodada até o efeito acabar, cada criatura que respira ar e estiver presa dessa forma deve obter sucesso em uma rolagem de desafio de Força ou sofrer 2d6 de dano. Uma criatura presa dessa maneira pode usar uma ação para fazer uma rolagem de desafio de Força. Em caso de sucesso, ela nada livremente e fica prostrada em um espaço desocupado escolhido por ela, a até 1 metro da esfera."},{"id":"agua-forcas-das-mares","nome":"Forças das Marés","tipo":"Ataque","trad":"Água","grau":3,"texto":"Área: Qualquer quantidade de criaturas a média distância Cada alvo deve fazer uma rolagem de desafio de Força com 1 revés. Se fracassar, ele é arrastado por 2d6 metros na sua direção ou para longe de você (à sua escolha) e fica aturdido por 1 rodada. Em caso de sucesso, ele é arrastado apenas metade da distância."},{"id":"agua-onda-de-frio","nome":"Onda de Frio","tipo":"Ataque","trad":"Água","grau":4,"texto":"Área: Um cone com 8 metros de comprimento, com origem em um ponto ao seu alcance Um frio letal se espalha por toda a área, congelando instantaneamente a água e demais líquidos à base de água, incluindo poções. O frio causa 7d6 de dano a tudo na área. Cada criatura na área que obtiver um sucesso em uma rolagem de desafio de Agilidade sofre metade do dano. Uma criatura que fica incapacitada por esse dano congela e morre instantaneamente."},{"id":"agua-vincular-genio-da-agua","nome":"Vincular Gênio da Água","tipo":"Utilitário","trad":"Água","grau":5,"texto":"Alvo: Um cubo de gelo, neve ou água, com 2 metros de lado, com origem em um ponto a longa distância Duração: 1 minuto Ao final da rodada em que você conjurou este feitiço, o alvo se torna um gênio da água de Tamanho 2. Você não pode encerrar este feitiço voluntariamente. Quando o gênio surgir, faça uma rolagem de ataque de Vontade contra a Vontade dele. Em caso de sucesso, o gênio fica compelido enquanto o efeito durar; se fracassar, ele se torna hostil a você."},{"id":"alteracao-compreensao","nome":"Compreensão","tipo":"Utilitário","trad":"Alteração","grau":0,"texto":"Alvo: Você e uma criatura ao seu alcance Duração: Concentração, até 1 minuto Você toca o alvo. Desde que saiba pelo menos um idioma, você pode se comunicar com o alvo pela duração do feitiço e você mantiver contato físico com ele, independentemente de vocês compartilharem o mesmo idioma ou não."},{"id":"alteracao-distorcer-aparencia","nome":"Distorcer Aparência","tipo":"Utilitário","trad":"Alteração","grau":0,"texto":"Alvo: Uma criatura ao seu alcance Duração: 1 minuto Você toca o alvo, fazendo com que sua forma pareça desfocada e imprecisa. Enquanto o efeito durar, quando o alvo tenta se esconder, faz a rolagem de desafio de Agilidade com 1 dádiva. Além disso, criaturas que podem vê-lo e fazem rolagens de ataque contra sua Defesa ou Agilidade com 1 revés."},{"id":"alteracao-ampliar-sentidos","nome":"Ampliar Sentidos","tipo":"Utilitário","trad":"Alteração","grau":1,"texto":"Alvo: Uma criatura ao seu alcance Duração: 1 hora Você toca o alvo. Enquanto o efeito durar, o alvo recebe um bônus de +5 em Percepção e pode enxergar em áreas obscurecidas por sombras ou escuridão como se estivessem iluminadas; no entanto, o alvo faz rolagens de desafio com 1 revés para resistir à cegueira ou surdez."},{"id":"alteracao-adaptacao-aquatica","nome":"Adaptação Aquática","tipo":"Utilitário","trad":"Alteração","grau":1,"texto":"Alvo: Uma criatura ao seu alcance Duração: 1 hora Você toca o alvo. Enquanto o efeito durar, o alvo respira na água como se estivesse respirando ar, move-se em velocidade total ao nadar e nunca precisa fazer rolagens de desafio para nadar."},{"id":"alteracao-escalada-aracnidea","nome":"Escalada Aracnídea","tipo":"Utilitário","trad":"Alteração","grau":1,"texto":"Alvo: Uma criatura ao seu alcance Duração: 1 hora Você toca o alvo. Enquanto o efeito durar, o alvo pode se mover na à sua velocidade total por paredes, tetos e saliências, sem jamais ter de fazer uma rolagem de desafio para escalar."},{"id":"alteracao-reforcar-atributo","nome":"Reforçar Atributo","tipo":"Utilitário","trad":"Alteração","grau":2,"texto":"Alvo: Uma criatura ao seu alcance Duração: 1 minuto Você toca o alvo. Escolha Força, Agilidade, Intelecto ou Vontade. Enquanto o efeito durar, o alvo faz todas rolagens de ataque ou desafio com o atributo reforçado com 1 dádiva."},{"id":"alteracao-reforcar-defesa","nome":"Reforçar Defesa","tipo":"Utilitário","trad":"Alteração","grau":2,"texto":"Alvo: : Uma criatura ao seu alcance Duração: : 1 minuto Você toca o alvo. Enquanto o efeito durar, o alvo recebe um bônus de +5 em Vida, e todas as rolagens de ataque contra ele são feitas com 1 revés."},{"id":"alteracao-alterar-tamanho","nome":"Alterar Tamanho","tipo":"Utilitário","trad":"Alteração","grau":3,"texto":"Alvo: Uma criatura ao seu alcance Duração: 1 minuto Você toca o alvo, que cresce ou encolhe e permanece com o novo Tamanho enquanto o efeito durar. Tudo o que ele veste ou carrega também cresce ou encolhe para se ajustar à nova forma. No entanto, se qualquer desses objetos deixar sua posse, retorna imediatamente ao tamanho normal. Se o alvo crescer, seu Tamanho dobra e ele recebe +10 em Vida. Seus ataques com armas causam 1d6 de dano extra se seu novo Tamanho for 3 ou menos, ou de 2d6 de dano extra se for 4 ou mais. Se o espaço que ele ocupa não for suficiente para acomodar o novo Tamanho, o alvo sofre 5d6 de dano e o efeito termina imediatamente. Se o alvo encolher, seu Tamanho é reduzido à metade. Ele causa metade do dano em ataques com armas, faz rolagens de ataque e desafio de Força com 1 revés e faz rolagens de ataque e desafio de Agilidade com 1 dádiva."},{"id":"alteracao-regeneracao","nome":"Regeneração","tipo":"Utilitário","trad":"Alteração","grau":3,"texto":"Alvo: Uma criatura viva ao seu alcance Duração: 1 minuto Você toca o alvo. Enquanto o efeito durar, ao final de cada rodada o alvo cura dano igual à metade de sua taxa de cura."},{"id":"alteracao-maleabilidade","nome":"Maleabilidade","tipo":"Utilitário","trad":"Alteração","grau":4,"texto":"Alvo: Uma criatura ao seu alcance Duração: 1 hora Você toca o alvo. Enquanto o efeito durar, o alvo pode se mover à sua Velocidade total em terreno difícil, atravessar espaços ocupados por outras criaturas, independentemente do Tamanho delas, e passar livremente por aberturas com pelo menos 3 cm de largura. Além disso, durante esse período, o alvo não pode ficar prostrado e é imune às aflições agarrado, imobilizado e lento."},{"id":"alteracao-despertar-potencial","nome":"Despertar Potencial","tipo":"Utilitário","trad":"Alteração","grau":5,"texto":"Alvo: Uma criatura ao seu alcance Duração: 1 hora Você toca o alvo. Escolha Força, Agilidade, Intelecto ou Vontade e role 1d6. Enquanto durar o feitiço, o atributo escolhido recebe um bônus igual ao número obtido no dado, até o valor máximo de 20. Esse aumento também afeta quaisquer características associada ao atributo em questão."},{"id":"ar-despertar-os-ares","nome":"Despertar Os Ares","tipo":"Utilitário","trad":"Ar","grau":0,"texto":"Área: Uma esfera com raio de 2 metros centralizada em um ponto ao seu alcance Duração: 1 minuto Você preenche toda a área com uma brisa leve, que se move com você durante todo o período. A brisa dissipa odores e poeira, espalha objetos leves como papéis, apaga velas e faz com que chamas maiores tremulem e dancem. Criaturas na área que atacam você com armas de arremesso ou de combate à distância fazem suas rolagens de ataque com 1 de revés."},{"id":"ar-rajada-de-vento","nome":"Rajada de Vento","tipo":"Ataque","trad":"Ar","grau":0,"texto":"Alvo: Uma criatura ou objeto a curta distância Um vento forte atinge o alvo. Faça uma rolagem de ataque de Vontade contra a Força do alvo. Com um sucesso, o vento desloca o alvo 1d6 metros para longe de você. Rolagem de Ataque 20+ O alvo cai no chão ao final deste movimento."},{"id":"ar-esfolar","nome":"Esfolar","tipo":"Ataque","trad":"Ar","grau":1,"texto":"Alvo: Uma criatura ou objeto a curta distância Areia e detritos carregados pelo vento esfolam seu alvo. Faça uma rolagem de ataque de Vontade contra a Força do alvo. Com um sucesso, o alvo sofre 2d6+3 de dano. Uma criatura viva incapacitada por esse dano morre instantaneamente — sua carne, se houver, é arrancada dos ossos. Rolagem de Ataque 20+ O alvo sofre 2d6 de dano extra."},{"id":"ar-evocar-ventania","nome":"Evocar Ventania","tipo":"Ataque","trad":"Ar","grau":1,"texto":"Área: Um cone, com 3 metros de comprimento, com origem em um ponto a curta distância Um vento uivante que dispersa vapores, nevoeiro, fumaça e gás na área. Chamas desprotegidas se alastram e objetos leves são levados pelo vento até a borda mais próxima da área. Cada criatura dentro da área deve obter sucesso em uma rolagem de desafio de Força ou será deslocada 1d6 metros para longe do ponto de origem. Criaturas voadoras fazem essa rolagem com 1 revés."},{"id":"ar-planar","nome":"Planar","tipo":"Utilitário","trad":"Ar","grau":1,"texto":"Alvo: Uma criatura a longa distância Duração: 1 minuto Desencadeada Você usa uma ação desencadeada para conjurar este feitiço quando vê o alvo cair. Enquanto o efeito durar, o alvo não sofre dano ao atingir o solo após uma queda. Se ele continuar caindo depois que o efeito terminar, sofrerá dano na altura restante."},{"id":"ar-silenciar-os-ares","nome":"Silenciar Os Ares","tipo":"Utilitário","trad":"Ar","grau":2,"texto":"Área: Uma esfera com raio de 4 metros centralizada em um ponto a média distância Duração: 1 hora Enquanto o efeito durar, nenhum som se propaga dentro da área. As criaturas na área ficam surdas e imunes a qualquer ataque baseado em sons, como o feitiço Trovoada ."},{"id":"ar-trovoada","nome":"Trovoada","tipo":"Ataque","trad":"Ar","grau":2,"texto":"Área: Uma esfera com raio de 10 metros centralizada em um ponto a média distância Uma onda de ruído estrondoso se espalha a partir do centro da área, causando 1d6+1 de dano a tudo que estiver ali. Cada criatura na área deve fazer uma rolagem de desafio de Força; em caso de sucesso, sofre metade do dano. Se fracassar, a criatura fica surda por 1 minuto."},{"id":"ar-conceder-voo","nome":"Conceder Voo","tipo":"Utilitário","trad":"Ar","grau":3,"texto":"Alvo: Uma criatura ao seu alcance Duração: 1 hora Você toca o alvo. Ele pode voar na à velocidade normal dele enquanto o efeito durar."},{"id":"ar-arremessar","nome":"Arremessar","tipo":"Ataque","trad":"Ar","grau":3,"texto":"Área: Um cilindro com 4 metros de altura e 4 metros de raio, centralizado em um ponto a longa distância Uma poderosa rajada de vento irrompe do ponto de origem. Cada criatura na área deve fazer uma rolagem de desafio de Força; Criaturas de Tamanho 1, ou menores, fazem a rolagem com 1 revés. Se fracassar, cai prostrada ao chão e é arremessada por 5d6 metros para longe do ponto de origem. Se a criatura se chocar com uma superfície sólida antes de percorrer toda a distância, tanto ela quanto a superfície atingida sofrem 1d6 de dano cada, mais 1d6 de dano extra para cada 5 metros restantes desse deslocamento (arredondado para baixo)."},{"id":"ar-criar-ciclone","nome":"Criar Ciclone","tipo":"Ataque","trad":"Ar","grau":4,"texto":"Área: Uma linha de 20 metros de comprimento, 10 metros de altura e 2 metros de largura, que se origina em um ponto em longa distância Um poderoso ciclone surge em uma das extremidades da área e atravessa toda a sua extensão, causando 3d6 de dano a qualquer coisa que estiver em seu caminho. Cada objeto solto atingido dessa forma é deslocado por 1d6 metros na direção que você escolher. Cada criatura atingida dessa maneira deve fazer uma rolagem de desafio de Força. Se fracassar, é deslocada por 1d6 metros na direção que você escolher e cai prostrada ao chão. Em caso de sucesso, sofre apenas metade do dano."},{"id":"ar-vincular-genio-do-vento","nome":"Vincular Gênio do Vento","tipo":"Utilitário","trad":"Ar","grau":5,"texto":"Alvo: Um cubo de ar com 2 metros de lado, que se origina em um ponto a longa distância Duração: 1 minuto No final da rodada em que você conjura este feitiço, o cubo alvo se transforma em um gênio do vento de Tamanho 2. Você não pode encerrar este feitiço voluntariamente. Quando o gênio surgir, faça uma rolagem de ataque de Vontade contra a Vontade dele. Em caso de sucesso, o gênio fica compelido enquanto o efeito durar; se fracassar, ele se torna hostil a você."},{"id":"arcana-armadura-arcana","nome":"Armadura Arcana","tipo":"Utilitário","trad":"Arcana","grau":0,"texto":"Requisitos: Você não pode estar com uma armadura. Duração: 4 horas Um campo de força invisível surge ao seu redor, concedendo um bônus de +2 à sua Defesa pela duração do feitiço. Além disso, pelo período, enquanto o feitiço estiver ativo, chuva comum não o atinge, ventos leves não o afetam e você não sofre os efeitos do frio ou do calor, embora ainda sofra dano por frio e fogo."},{"id":"arcana-dardo-magico","nome":"Dardo Mágico","tipo":"Ataque","trad":"Arcana","grau":0,"texto":"Alvo: Uma criatura ou objeto a longa distância Você dispara um dardo mágico da ponta de seu dedo. Esse dardo atinge o alvo automaticamente, desde que não haja obstáculo algum entre você e o alvo. O alvo sofre 1d3 + 1 de dano."},{"id":"arcana-escudo-arcano","nome":"Escudo Arcano","tipo":"Utilitário","trad":"Arcana","grau":1,"texto":"Duração: 1 minuto Enquanto o efeito durar, um escudo de energia o protege e impõe 1 revés nas rolagens de ataque feitas contra sua Defesa ou Agilidade. Desencadeada Quando uma criatura faz um ataque contra sua Defesa ou Agilidade, você pode conjurar este feitiço com uma ação desencadeada. A criatura que desencadeou o ataque faz a rolagem com 3 reveses e o efeito se encerra logo em seguida."},{"id":"arcana-visao-arcana","nome":"Visão Arcana","tipo":"Utilitário","trad":"Arcana","grau":1,"texto":"Duração: 1 minuto Enquanto o efeito durar, você vê auras ao redor de criaturas, objetos e em áreas afetadas por magia. A critério do MJ, você também pode saber a qual tradição pertence a magia."},{"id":"arcana-dardos-certeiros","nome":"Dardos Certeiros","tipo":"Ataque","trad":"Arcana","grau":1,"texto":"Alvo: Até três criaturas ou objetos em longa distância Você dispara sete dardos mágicos da ponta do seu dedo, que se dividem entre os alvos escolhidos por você. Cada dardo acerta automaticamente, desde que não haja obstáculo algum entre você e o alvo. O alvo sofre 1 ponto de dano para cada dardo que o atinge."},{"id":"arcana-fortalecer-magia","nome":"Fortalecer Magia","tipo":"Utilitário","trad":"Arcana","grau":2,"texto":"Duração: 1 minuto Enquanto o efeito durar, ao conjurar um feitiço de ataque você faz todas as rolagens de ataque com 1 dádiva; rolagens de desafio para resistir ao efeito de seu feitiço são feitas com 1 revés."},{"id":"arcana-dardos-explosivos","nome":"Dardos Explosivos","tipo":"Ataque","trad":"Arcana","grau":2,"texto":"Alvo: Até três criaturas ou objetos em longa distância Três dardos mágicos voam da ponta do seu dedo, e se dividem entre os alvos escolhidos por você. Cada dardo acerta automaticamente, desde que não haja obstáculo algum entre você e o alvo. Cada dardo causa 1 ponto de dano ao alvo e explode em um raio de 1 metro a partir de um ponto dentro do espaço do alvo. Tudo que estiver nessa área sofre 1d6+1 de dano, ou metade desse valor se obtiver um sucesso em uma rolagem de desafio de Agilidade."},{"id":"arcana-relampago-arcano","nome":"Relâmpago Arcano","tipo":"Ataque","trad":"Arcana","grau":3,"texto":"Área: Um cone, com 5 metros de comprimento, com origem em um ponto ao seu alcance O relâmpago causa 5d6 de dano a tudo que estiver em sua área. Cada criatura dentro da área deve fazer uma rolagem de desafio de Agilidade, sofrendo apenas metade do dano em caso de sucesso."},{"id":"arcana-destruir-magia","nome":"Destruir Magia","tipo":"Utilitário","trad":"Arcana","grau":3,"texto":"Área: Um cubo com 5 metros de lado, com origem em um ponto a média distância Todos os efeitos criados por feitiços de grau 3 ou inferior que estejam afetando algo na área terminam imediatamente."},{"id":"arcana-coletar-magia","nome":"Coletar Magia","tipo":"Utilitário","trad":"Arcana","grau":4,"texto":"Duração: Veja o efeito Role 1d6+3 para determinar quantos pontos de energia mágica você coleta. Você mantém esses pontos até completar um descanso ou até gastá-los. Enquanto ainda tiver pontos restantes, não poderá conjurar coletar magia novamente. Você pode conjurar um feitiço que tenha aprendido gastando uma quantidade de pontos de energia mágica igual ao grau do feitiço (mínimo 1) sem gastar uma conjuração desse feitiço."},{"id":"arcana-represalia-arcana","nome":"Represália Arcana","tipo":"Ataque","trad":"Arcana","grau":5,"texto":"Duração: 4 horas; veja o efeito Você ganha um bônus de +5 na Defesa pela duração do feitiço. Na próxima vez que uma criatura a curta distância de você obtiver sucesso em uma rolagem de ataque com arma contra você, esse efeito termina e o sucesso se transforma automaticamente em fracasso. A criatura que desencadeou o efeito deve fazer uma rolagem de desafio de Força. Se fracassar, ela sofre 10d6 de dano, é lançada 2d6 metros para longe de você e fica prostrada. Em caso de sucesso, ela sofre metade do dano."},{"id":"batalha-celeridade","nome":"Celeridade","tipo":"Utilitário","trad":"Batalha","grau":0,"texto":"Você se move até o dobro da sua Velocidade. Este movimento não desencadeia ataques livres. Desencadeada Em seu turno, você pode usar uma ação desencadeada para conjurar este feitiço. Neste caso, você se move até sua Velocidade total sem desencadear ataques livres."},{"id":"batalha-ataque-aprimorado","nome":"Ataque Aprimorado","tipo":"Ataque","trad":"Batalha","grau":0,"texto":"Como parte da conjuração deste feitiço, você deve fazer um ataque com uma arma. Você faz uma rolagem de ataque com 1 dádiva e pode usar seu Intelecto ao invés do atributo normal do ataque."},{"id":"batalha-estancar-ferimentos","nome":"Estancar Ferimentos","tipo":"Utilitário","trad":"Batalha","grau":1,"texto":"Você cura uma quantidade de dano igual à sua taxa de cura. Desencadeada Em seu turno, você pode usar uma ação desencadeada para conjurar este feitiço. Neste caso, recupera apenas metade da sua taxa de cura."},{"id":"batalha-ataque-potente","nome":"Ataque Potente","tipo":"Ataque","trad":"Batalha","grau":1,"texto":"Como parte da conjuração deste feitiço, você deve fazer um ataque com uma arma. Você faz uma rolagem de ataque com 1 dádiva e pode usar seu Intelecto ao invés do atributo normal do ataque. Em caso de sucesso, o alvo sofre 2d6 de dano extra."},{"id":"batalha-ataque-retumbante","nome":"Ataque Retumbante","tipo":"Ataque","trad":"Batalha","grau":1,"texto":"Como parte da conjuração deste feitiço, você deve fazer um ataque com uma arma. Você faz uma rolagem de ataque com 1 dádiva e pode usar seu Intelecto em vez do atributo normal do ataque. Em caso de sucesso, o alvo sofre dano normalmente e fica aturdido por 1 rodada."},{"id":"batalha-impacto-da-montanha","nome":"Impacto da Montanha","tipo":"Ataque","trad":"Batalha","grau":2,"texto":"Você voa até o dobro da sua Velocidade então cai com força ao chão. Ao tocar o solo, uma onda de choque se espalha pelo chão em um raio de 4 metros a partir de um ponto dentro do seu espaço. Cada criatura que esteja no chão deve fazer uma rolagem de desafio de Agilidade. Se fracassar, a criatura sofre 2d6 de dano e fica prostrada."},{"id":"batalha-varredura-mortal","nome":"Varredura Mortal","tipo":"Ataque","trad":"Batalha","grau":2,"texto":"Alvo: Cada criatura, à sua escolha, ao seu alcance Você varre ao seu redor com sua arma corpo a corpo em um giro letal, causando 3d6+3 de dano a cada alvo, em vez do dano normal da arma. Cada alvo sofre metade do dano se obtiver sucesso em uma rolagem de desafio de Agilidade."},{"id":"batalha-proeza-de-batalha","nome":"Proeza de Batalha","tipo":"Utilitário","trad":"Batalha","grau":3,"texto":"Duração: 1 minuto Você aprimora suas habilidades de luta. Enquanto o efeito durar, sempre que atacar com uma arma rolar o ataque duas vezes e usar o melhor resultado. Além disso, seus ataques com armas causam 1d6 de dano extra pela duração do feitiço."},{"id":"batalha-ataque-meteorico","nome":"Ataque Meteórico","tipo":"Ataque","trad":"Batalha","grau":3,"texto":"Você se move até o dobro da sua Velocidade em linha reta. Durante esse movimento, você faz um ataque com arma contra cada criatura que estiver ao seu alcance — mas apenas uma vez por criatura. Para cada ataque após o primeiro, você faz a rolagem de ataque com 1 revés; cada ataque causa 1d6 de dano extra. Você pode usar seu Intelecto em vez do atributo normal do ataque."},{"id":"batalha-muralha-de-espadas","nome":"Muralha de Espadas","tipo":"Ataque","trad":"Batalha","grau":4,"texto":"Área: Uma linha de 20 metros de comprimento, 5 metros de altura e 2 metros de largura, com origem em um ponto a longa distância Duração: 1 hora Uma muralha de espadas afiadas surge na área, permanecendo pela duração do feitiço. Ela fornece cobertura completa a tudo o que está atrás dela. Quando a muralha surge, tudo em sua área sofre 5d6 de dano. Um sucesso em uma rolagem de desafio de Agilidade reduz o dano à metade. Criaturas podem se mover pela área, que conta como terreno difícil. Quando uma criatura vinda de fora entra na área, ou se estiver dentro da área ao final da rodada, ela precisa de um sucesso em uma rolagem de desafio de Agilidade ou sofre 3d6 de dano."},{"id":"batalha-presteza-do-relampago","nome":"Presteza do Relâmpago","tipo":"Ataque","trad":"Batalha","grau":5,"texto":"Área: Uma esfera com raio igual à metade da sua Velocidade, centralizada em um ponto ao seu alcance Você se move como um borrão, atacando furiosamente por onde passa. Cada criatura escolhida por você dentro da área de efeito deve fazer uma rolagem de desafio de Agilidade com 1 revés. Se fracassar, ela sofre 4d6+3 de dano. Em seguida, você se move até a metade da sua Velocidade. Este movimento não desencadeia ataques livres."},{"id":"cancao-projetar-voz","nome":"Projetar Voz","tipo":"Utilitário","trad":"Canção","grau":0,"texto":"Duração: 1 minuto Enquanto o efeito durar, tudo o que você disser ou cantar pode ser ouvido a uma distância de até 1,5 quilômetro."},{"id":"cancao-cancao-da-amizade","nome":"Canção da Amizade","tipo":"Ataque","trad":"Canção","grau":0,"texto":"Alvo: Qualquer criatura escolhida por você a curta distância e que possa ouvi-lo Você se concentra por 1 minuto, e canta durante esse período. Quando terminar, cada alvo deve fazer uma rolagem de desafio de Vontade. Se fracassar, o alvo fica encantado por 1 hora ou até sofrer dano."},{"id":"cancao-cancao-da-bravura","nome":"Canção da Bravura","tipo":"Utilitário","trad":"Canção","grau":1,"texto":"Duração: 1 minuto Ao conjurar este feitiço e em cada um dos seus turnos enquanto ele durar, escolha uma criatura a curta distância que possa ouvilo. O alvo causa 1d6 de dano extra em ataques com armas corpo a corpo durante 1 rodada. O efeito termina imediatamente se você parar de cantar ou conjurar outro feitiço."},{"id":"cancao-cancao-da-coragem","nome":"Canção da Coragem","tipo":"Utilitário","trad":"Canção","grau":1,"texto":"Alvo: Qualquer criatura escolhida por você a curta distância e que possa ouvi-lo Duração: 1 minuto Pela duração do feitiço, cada alvo fica imune às aflições encantado, compelido ou amedrontado enquanto permanecer a curta distância e puder ouvi-lo. O efeito termina imediatamente se você parar de cantar ou conjurar outro feitiço."},{"id":"cancao-cancao-da-inspiracao","nome":"Canção da Inspiração","tipo":"Utilitário","trad":"Canção","grau":1,"texto":"Duração: 1 minuto Ao conjurar esse feitiço e em cada um dos seus turnos enquanto ele durar, escolha uma criatura a curta distância que possa ouvilo. O alvo faz a sua próxima rolagem de ataque ou desafio com 2 dádivas. O efeito termina imediatamente se você parar de cantar ou conjurar outro feitiço."},{"id":"cancao-cancao-da-cura","nome":"Canção da Cura","tipo":"Utilitário","trad":"Canção","grau":2,"texto":"Alvo: Qualquer criatura escolhida por você a curta distância e que possa ouvi-lo Você se concentra por 1 minuto, e canta durante esse período. Ao terminar de cantar, cada alvo que estava a curta distância durante toda a sua apresentação cura dano equivalente à sua própria taxa de cura."},{"id":"cancao-cancao-do-fascinio","nome":"Canção do Fascínio","tipo":"Ataque","trad":"Canção","grau":2,"texto":"Duração: Concentração, até 1 minuto Ao conjurar o feitiço e quando usar uma ação para se concentrar nele, escolha uma criatura a curta distância que possa ouvi-lo. O alvo deve obter sucesso em uma rolagem de desafio de Vontade ou ficará encantado pela duração do feitiço. Enquanto estiver encantada dessa forma, a criatura só poderá realizar turnos lentos e deverá, em seu próprio turno, mover-se na sua direção caso esteja a mais de 10 metros de você. O efeito termina imediatamente se você parar de cantar ou conjurar outro feitiço."},{"id":"cancao-cancao-da-libertinagem","nome":"Canção da Libertinagem","tipo":"Ataque","trad":"Canção","grau":3,"texto":"Duração: Concentração, até 1 minuto Ao conjurar o feitiço e quando usar uma ação para se concentrar nele, escolha uma criatura a curta distância que possa ouvi-lo. O alvo deve fazer uma rolagem de desafio de Vontade. Em caso de sucesso, ele fica imune a esta conjuração do feitiço; se fracassar, fica debilitado. Enquanto estiver debilitada dessa maneira, a criatura também fica lenta."},{"id":"cancao-cancao-do-pavor","nome":"Canção do Pavor","tipo":"Ataque","trad":"Canção","grau":3,"texto":"Duração: Concentração, até 1 minuto Ao conjurar o feitiço e quando usar uma ação para se concentrar nele, escolha uma criatura a curta distância que possa ouvi-lo. O alvo deve fazer uma rolagem de desafio de Vontade. Em caso de sucesso, ele fica imune a esta conjuração do feitiço; se fracassar, fica amedrontado. Enquanto estiver amedrontada dessa maneira, a criatura deve usar sua ação em cada rodada para se afastar de você pelo caminho mais segura que estiver disponível. Se a criatura não puder ouvi-lo ao final da rodada, esta aflição é removida."},{"id":"cancao-cancao-do-adormecer","nome":"Canção do Adormecer","tipo":"Ataque","trad":"Canção","grau":4,"texto":"Duração: Concentração, até 1 minuto Ao conjurar o feitiço e quando usar uma ação para se concentrar nele, escolha uma criatura a curta distância que possa ouvi-lo. O alvo deve fazer uma rolagem de desafio de Vontade. Em caso de sucesso, ele fica imune a esta conjuração do feitiço; se fracassar, fica lento. Enquanto estiver lenta dessa maneira, a criatura também fica fatigada. Se a criatura não puder ouvi-lo ao final da rodada, estas aflições são removidas. Se o alvo já estiver lento, ele cai no sono por 1 hora."},{"id":"cancao-cancao-dos-herois","nome":"Canção dos Heróis","tipo":"Utilitário","trad":"Canção","grau":5,"texto":"Alvo: Até três criaturas a curta distância que possam ouvi-lo Duração: 1 minuto Enquanto o efeito durar, ou até que ele não consiga mais ouvi-lo, cada alvo recebe um bônus de +20 em Vida, um bônus de +2 em Velocidade, e faz rolagens de ataque e desafio com 2 dádivas. O efeito termina imediatamente se você parar de cantar ou conjurar outro feitiço."},{"id":"caos-dadiva-do-caos","nome":"Dádiva do Caos","tipo":"Utilitário","trad":"Caos","grau":0,"texto":"Duração: 1 minuto Enquanto o efeito durar, você rola um dado do caos (1d6) sempre que fizer uma rolagem de ataque ou de desafio. Se tirar um número ímpar, aplique o resultado como penalidade na rolagem do d20; se tirar um número par, aplique o resultado como bônus à rolagem."},{"id":"caos-raio-erratico","nome":"Raio Errático","tipo":"Ataque","trad":"Caos","grau":0,"texto":"Alvo: Uma criatura ou objeto a média distância Uma gota colorida, brilhante e efervescente, voa da sua mão. Faça uma rolagem de ataque de Vontade contra a Agilidade do alvo. Em caso de sucesso, o alvo sofre 1d6 de dano. Após a rolagem de ataque, role um d6. Se o resultado for 6, repita o ataque contra um alvo diferente, amigo ou inimigo, a média distância do alvo anterior. Se houver mais de um alvo possível, você escolhe quem é afetado. Rolagem de Ataque 20+ O alvo sofre 1d6 de dano extra."},{"id":"caos-devastacao-caprichosa","nome":"Devastação Caprichosa","tipo":"Ataque","trad":"Caos","grau":1,"texto":"Alvo: Uma criatura ou objeto a média distância Uma bola de energia cintilante salta da sua mão. Faça uma rolagem de ataque de Vontade contra a Agilidade do alvo e role um d6. Se tirar um número ímpar, aplique o resultado como penalidade na rolagem de Ataque; se tirar um número par, aplique o resultado como bônus à rolagem. Em caso de sucesso, o alvo sofre 2d6 de dano e mais 2d6 de dano extra se sua rolagem de ataque sofreu uma penalidade devido a este feitiço. Rolagem de Ataque 20+ O alvo também se teletransporta 1d6 metros para um espaço desocupado na direção que você escolher."},{"id":"caos-distorcao-espacial","nome":"Distorção Espacial","tipo":"Utilitário","trad":"Caos","grau":1,"texto":"Role 2d6. Você se teletransporta para um espaço desocupado à sua escolha a uma distância em metros igual ao resultado total da rolagem. Desencadeada Você pode usar uma ação desencadeada para conjurar este feitiço no seu turno. Nesse caso, você rola 1d6 ao invés do 2d6 para determinar a distância teletransportada."},{"id":"caos-escudo-iridescente","nome":"Escudo Iridescente","tipo":"Utilitário","trad":"Caos","grau":1,"texto":"Duração: 1 hora; ver o efeito Um campo cintilante e colorido surge ao seu redor. Role um d6 e adicione o número obtido no dado como bônus à sua Defesa. Cada vez que uma criatura fizer um ataque contra sua Defesa, reduza esse bônus em 1 até um mínimo de 0 encerrando, assim, o efeito."},{"id":"caos-cor-da-magia","nome":"Cor da Magia","tipo":"Ataque","trad":"Caos","grau":2,"texto":"Alvo: Um ponto no espaço a média distância Um globo colorido voa rapidamente da sua mão em direção ao alvo. Ao atingi-lo, ou se colidir com uma criatura ou objeto sólido antes do alvo, ele explode. Energia caótica e colorida se espalha por uma esfera com raio de 1 metro, centralizada no alvo ou em um ponto no espaço da criatura ou objeto. Tudo na área sofre 1d6+1 de dano. Se você obteve um resultado ímpar no dado do dano, tudo que estiver na área sofre 3d6 de dano extra."},{"id":"caos-tremeluzir","nome":"Tremeluzir","tipo":"Utilitário","trad":"Caos","grau":2,"texto":"Duração: 1d6 minutos Você desaparece e reaparece de forma errática. Ao final de cada rodada, durante a duração do feitiço, role um d6. Você se teletransporta para um espaço desocupado a até um número de metros igual ao resultado. Se o resultado for um número ímpar, o MJ escolhe onde você aparece. Se o resultado for um número par, você escolhe."},{"id":"caos-lanca-caotica","nome":"Lança Caótica","tipo":"Ataque","trad":"Caos","grau":3,"texto":"Área: Uma linha moldável, com 15 metros de comprimento e 2 metros de largura, com origem em um ponto ao seu alcance Uma torrente de energia colorida se espalha por toda a área. Cada criatura dentro dessa área deve fazer uma rolagem de desafio de Vontade. Se fracassar sofre 5d6+5 de dano; em caso de sucesso, cura 2d6+5 de dano."},{"id":"caos-magia-selvagem","nome":"Magia Selvagem","tipo":"Utilitário","trad":"Caos","grau":3,"texto":"Área: Uma esfera com raio de 1d6 metros centralizada em um ponto ao seu alcance Luzes bizarras, sons estranhos e outros efeitos esquisitos se espalham por toda a área. Role um d20 para ver o que acontece."},{"id":"caos-campo-de-espelhos","nome":"Campo de Espelhos","tipo":"Utilitário","trad":"Caos","grau":4,"texto":"Área: Uma linha moldável, com 10 metros de comprimento, 5 metros de altura e 1 metro de largura com origem em um ponto a longa distância Duração: 1 minuto Uma barreira, semelhante a um espelho, preenche toda a área pela duração do feitiço, obscurecendo completamente a área por trás dela. Quando uma criatura adentrar nesse espaço, role um d6. Se o resultado for um número par, a criatura se move 1 metro através da barreira até um espaço desocupado do outro lado, na direção que ela escolher. Se for um número ímpar, a criatura é teletransportada para um espaço desocupado à sua escolha sobre uma superfície horizontal sólida, por uma distância em metros igual ao resultado."},{"id":"caos-singularidade","nome":"Singularidade","tipo":"Ataque","trad":"Caos","grau":5,"texto":"Área: Uma esfera com raio de 10 metros centralizada em um ponto a longa distância Duração: 1 minuto Um grumo fervilhante multicolorido surge no ponto de origem, permanecendo nessa área pela duração do feitiço. Uma vez conjurado o feitiço, objetos livres na área se movem por 2d6 metros em direção ao ponto de origem. Quando você conjura o feitiço, cada criatura que estiver ou entrar na área deve fazer uma rolagem de desafio de Força com 1 revés. Se fracassar, a criatura se move por 2d6 metros em direção ao ponto de origem, e não pode se afastar dele pela duração do feitiço. Qualquer criatura ou objeto que alcance esse ponto sofre 10d6 de dano. Uma criatura incapacitada por esse dano é completamente apagada da existência — seu corpo e alma desaparecem para sempre. O grumo explode quando o efeito terminar, causando 4d6 de dano a tudo que estiver na área do feitiço. Cada criatura dentro da área de efeito deve fazer uma rolagem de desafio de Força. Se fracassar, ela fica prostrada; em caso de sucesso, sofre apenas metade do dano."},{"id":"celestial-feixe-ardente","nome":"Feixe Ardente","tipo":"Ataque","trad":"Celestial","grau":0,"texto":"Alvo: Uma criatura ou objeto a média distância Um feixe flamejante dispara da sua mão. Faça uma rolagem de ataque de Vontade contra a Agilidade do alvo. Em caso de sucesso, o alvo sofre 1d6 de dano. Rolagem de Ataque 20+ O alvo também fica cego por 1 rodada."},{"id":"celestial-luz","nome":"Luz","tipo":"Utilitário","trad":"Celestial","grau":0,"texto":"Alvo: Um objeto ao seu alcance Duração: 1 hora Você toca o alvo e ele emana luz em 5 metros de raio pela duração do feitiço."},{"id":"celestial-clarao","nome":"Clarão","tipo":"Ataque","trad":"Celestial","grau":1,"texto":"Alvo: Uma criatura dotada de visão, a curta distância Um intenso clarão de luz surge diante do alvo. Faça uma rolagem de ataque de Vontade contra a Percepção do alvo. Em caso de sucesso, o alvo fica cego por 1 rodada. Rolagem de Ataque 20+ O alvo fica cego por 1 minuto."},{"id":"celestial-explosao-de-arco-iris","nome":"Explosão de Arco-Íris","tipo":"Ataque","trad":"Celestial","grau":1,"texto":"Alvo: Um ponto no espaço a média distância Uma partícula cintilante voa em linha reta da ponta do seu dedo em direção ao alvo. Ao atingi-lo, ou se colidir com uma criatura ou objeto sólido antes do alvo, a partícula explode em luzes iridescentes. As luzes se espalham por uma esfera com raio de 1 metro, centrada no alvo ou em um ponto no espaço da criatura"},{"id":"celestial-luz-permanente","nome":"Luz Permanente","tipo":"Utilitário","trad":"Celestial","grau":1,"texto":"Alvo: Um objeto ao seu alcance Duração: 8 horas Você toca o alvo e ele emana luz em 10 metros de raio pela duração do feitiço. ou objeto. Cada criatura dotada de visão dentro da área deve obter um sucesso em uma rolagem de desafio de Percepção, ou ficará aturdida por 1 rodada."},{"id":"celestial-alvorecer","nome":"Alvorecer","tipo":"Utilitário","trad":"Celestial","grau":2,"texto":"Área: Uma esfera com raio de 10 metros centralizada em um ponto a longa distância Duração: 1 hora Enquanto o efeito durar, a luz do sol banha toda a área, dissipando sombras ou escuridão mágicas criadas por feitiços de grau 2 ou inferior."},{"id":"celestial-raios-de-sol","nome":"Raios de Sol","tipo":"Ataque","trad":"Celestial","grau":2,"texto":"Alvo: Até três criaturas ou objetos a média distância Três feixes de luz flamejantes disparam de sua mão, dividindose entre os alvos escolhidos por você. Para cada feixe, faça uma rolagem de ataque de Vontade contra a Agilidade do alvo. Em caso de sucesso, o alvo sofre 1d6 de dano. Se o alvo for dotado de visão, também fica debilitado por 1 rodada. Rolagem de Ataque 20+ O alvo sofre 1d3 de dano extra."},{"id":"celestial-radiacao","nome":"Radiação","tipo":"Ataque","trad":"Celestial","grau":3,"texto":"Área: Uma esfera com raio de 3 metros centralizada em um ponto a longa distância Duração: 1 minuto Uma tênue luz verde se espalha pela área, transformando escuridão em sombras pela duração do feitiço. Tudo na área sofre 1d6 de dano quando você conjura o feitiço e ao final de cada rodada subsequente por sua duração. Cada criatura que sofrer dano dessa maneira deve fazer uma rolagem de desafio de Força. Se fracassar, fica fatigada por 1 rodada e lenta enquanto estiver fatigada dessa maneira. Em caso de sucesso, a criatura sofre metade do dano."},{"id":"celestial-estrela-cadente","nome":"Estrela Cadente","tipo":"Ataque","trad":"Celestial","grau":3,"texto":"Alvo: Um ponto no espaço a média distância Um ponto de luz branca surge em qualquer lugar dentro do alcance e dispara em direção ao alvo. Ao atingi-lo, ou se colidir com uma criatura ou objeto sólido antes do alvo, ele explode. Chamas se espalham por uma esfera de 3 metros de raio centralizada no alvo, ou em um ponto no espaço da criatura ou objeto, causando 2d6+2 de dano a tudo que está na área. Cada criatura dentro da área de efeito deve fazer uma rolagem de desafio de Força. Se fracassar, fica debilitada por 1 rodada; em caso de sucesso, sofre apenas metade do dano."},{"id":"celestial-supernova","nome":"Supernova","tipo":"Ataque","trad":"Celestial","grau":4,"texto":"Área: Uma esfera com raio de 8 metros centralizada em um ponto ao seu alcance Uma explosão de luz ofuscante e se espalha pela área de efeito. Cada criatura dentro da área, exceto você, sofre 2d6+2 de dano e deve fazer uma rolagem de desafio de Força. Se fracassar, fica cega por 1 rodada; em caso de sucesso, sofre apenas metade do dano."},{"id":"celestial-labareda-solar","nome":"Labareda Solar","tipo":"Ataque","trad":"Celestial","grau":5,"texto":"Área: Uma linha de 25 metros de comprimento e 1 metro de largura, com origem em um ponto ao seu alcance Você lança um feixe de luz brilhante e flamejante de sua mão, que causa 3d6+3 de dano a tudo que estiver na área de efeito. Cada criatura que sofrer dano dessa maneira deve fazer uma rolagem de desafio de Força. Se fracassar, fica cega por 1 rodada; em caso de sucesso, sofre apenas metade do dano."},{"id":"conjuracao-conjuracao-direta","nome":"Conjuração Direta","tipo":"Utilitário","trad":"Conjuração","grau":0,"texto":"Alvo: Uma criatura a curta distância criada por um de seus feitiços da tradição de Conjuração Você move o alvo até metade da sua própria velocidade."},{"id":"conjuracao-conjurar-item-util","nome":"Conjurar Item Útil","tipo":"Utilitário","trad":"Conjuração","grau":0,"texto":"Área: Um cubo com 1 metros de lado, com origem em um ponto ao seu alcance Duração: 1 minuto Um objeto de Tamanho 1, ou menor, que não é mágico nem vale mais do que 1 xp, surge na área."},{"id":"conjuracao-conjurar-arma","nome":"Conjurar Arma","tipo":"Utilitário","trad":"Conjuração","grau":1,"texto":"Duração: 1 hora Uma arma, ou um conjunto de munições, surge em suas mãos ou aos seus pés, caso você não tenha uma mão livre."},{"id":"conjuracao-conjurar-banquete","nome":"Conjurar Banquete","tipo":"Utilitário","trad":"Conjuração","grau":1,"texto":"Área: Um cubo com 2 metros de lado, com origem em um ponto ao seu alcance Duração: 1 hora; veja o efeito Um banquete suntuoso e salutar, suficiente para sustentar até cinco criaturas por um dia, surge nas superfícies horizontais dentro da área. Tudo aquilo que não for consumido desaparece quando o efeito termina."},{"id":"conjuracao-conjurar-monstro-pequeno","nome":"Conjurar Monstro Pequeno","tipo":"Utilitário","trad":"Conjuração","grau":1,"texto":"Área: Um cubo com 1 metro de lado, com origem em um ponto a média distância, sobre uma superfície sólida. Duração: 1 minuto Um monstro pequeno compelido surge na área."},{"id":"conjuracao-conjurar-corceis","nome":"Conjurar Corcéis","tipo":"Utilitário","trad":"Conjuração","grau":2,"texto":"Alvo: Um cubo com 10 metros de lado, com origem em um ponto a média distância, sobre uma superfície sólida Duração: 2 horas Um grupo de 1d6 corcéis (como cavalo ) surge na área. Eles podem ter qualquer aparência que você escolher. Os corcéis conjurados são amigáveis e se tornam compelidos por qualquer criatura que os monte. Sacrifício Você pode gastar uma conjuração deste feitiço para usar conjurar monstro pequeno ."},{"id":"conjuracao-conjurar-monstro-medio","nome":"Conjurar Monstro Médio","tipo":"Utilitário","trad":"Conjuração","grau":2,"texto":"Área: Um cubo com 2 metro de lado, com origem em um ponto a média distância, sobre uma superfície sólida. Duração: 1 minuto Um monstro médio compelido ou dois monstros pequenos compelidos surgem na área."},{"id":"conjuracao-conjurar-monstro-grande","nome":"Conjurar Monstro Grande","tipo":"Utilitário","trad":"Conjuração","grau":3,"texto":"Área: Um cubo com 2 metro de lado, com origem em um ponto a média distância, sobre uma superfície sólida. Duração: 1 minuto Um monstro grande compelido ou dois monstros médios compelidos surgem na área."},{"id":"conjuracao-conjurar-muralha","nome":"Conjurar Muralha","tipo":"Utilitário","trad":"Conjuração","grau":3,"texto":"Área: Uma linha moldável, com 10 metros de comprimento, 5 metros de altura e 2 metros de largura, com origem em um ponto a longa distância, com qualquer orientação, desde que pelo menos dois lados estejam apoiados em superfícies sólidas Duração: 1 hora; veja o efeito Uma muralha de pedra preenche a área, permanecendo no local pela duração do feitiço ou até ser destruída. A muralha fornece cobertura completa a tudo o que está atrás dela. Cada 1 metro cúbico da muralha possui Defesa 5, Vida 50, e desaparece ao ser destruído."},{"id":"conjuracao-conjurar-abrigo","nome":"Conjurar Abrigo","tipo":"Utilitário","trad":"Conjuração","grau":4,"texto":"Área: Um cubo com 20 metros de lado, com origem em um ponto a longa distância e apoiado em uma superfície sólida ou líquida Duração: 12 horas; veja o efeito Você deve se concentrar por 1 minuto, mentalizando uma construção ou ilha. Ao final desse período, a construção ou a ilha que você mentalizou surge na área, permanecendo no local pela duração do feitiço. Se você conjurar uma construção, deve decidir os detalhes de sua aparência, como entradas, janelas e quantidade de cômodos. A construção inclui camas para até dez pessoas, cadeiras, mesas, comida e bebida suficientes para até dez pessoas, e uma lareira completa com fogo aceso. Se conjurar uma ilha, poderá criar acomodações para até dez pessoas como se tivesse criado uma construção, mas na forma de bangalôs ou cabanas. Sacrifício Você pode gastar uma conjuração deste feitiço para usar conjurar monstro grande ."},{"id":"conjuracao-conjurar-monstro-enorme","nome":"Conjurar Monstro Enorme","tipo":"Utilitário","trad":"Conjuração","grau":5,"texto":"Área: Um cubo com 4 metros de lado, com origem em um ponto a média distância, apoiado sobre uma superfície sólida Duração: 1 minuto Um monstro enorme compelido ou dois monstros grandes compelidos aparecem na área."},{"id":"destruicao-arruinar","nome":"Arruinar","tipo":"Ataque","trad":"Destruição","grau":0,"texto":"Alvo: Uma criatura ou objeto a curta distância Você sofre 1 ponto de dano. O alvo sofre 1d6 de dano; se for uma criatura, deve fazer uma rolagem de desafio de Força; se fracassar, fica fatigada por 1 minuto."},{"id":"destruicao-quebrar","nome":"Quebrar","tipo":"Ataque","trad":"Destruição","grau":0,"texto":"Alvo: Um objeto de Tamanho 1/2 ou menor a curta distância Você sofre 1 ponto de dano. O alvo sofre dano igual à Vida dele."},{"id":"destruicao-despedacar","nome":"Despedaçar","tipo":"Ataque","trad":"Destruição","grau":1,"texto":"Alvo: Um objeto feito de vidro, metal ou pedra a média distância em seu campo de visão Você sofre 2 pontos de dano e o alvo sofre 3d6 de dano. Se esse dano destruir o alvo, ele explode e lança destroços em um raio de 2 metros a partir de um ponto dentro de seu espaço, causando 1d6 de dano a tudo que estiver dentro da área. Uma criatura dentro da área que conseguir um sucesso em uma rolagem de desafio de Agilidade sofre metade do dano."},{"id":"destruicao-dilacerar","nome":"Dilacerar","tipo":"Ataque","trad":"Destruição","grau":1,"texto":"Alvo: Uma criatura a curta distância em seu campo de visão Você sofre 2 pontos de dano. Faça uma rolagem de ataque de Vontade contra a Agilidade do alvo. Com um sucesso, o alvo sofre 3d6+1 de dano. Rolagem de Ataque 20+ O alvo sofre 2d6 de dano extra."},{"id":"destruicao-dissolver","nome":"Dissolver","tipo":"Ataque","trad":"Destruição","grau":1,"texto":"Alvo: Uma criatura com corpo físico ao seu alcance Você sofre 2 pontos de dano. Faça uma rolagem de ataque de Vontade contra a Força do alvo. Em caso de sucesso, o alvo sofre 1d6+1 de dano do seu toque corrosivo e fica debilitado por 1 minuto. Se o dano deixar o alvo debilitado, ele morre instantaneamente e se dissolve em gosma; tudo o que ele vestia ou carregava vai ao chão no espaço anteriormente ocupado por ele. Rolagem de Ataque 20+ O alvo sofre 1d6 de dano extra."},{"id":"destruicao-poder-entropico","nome":"Poder Entrópico","tipo":"Utilitário","trad":"Destruição","grau":2,"texto":"Duração: 1 minuto Você sofre 3 pontos de dano. Enquanto o efeito durar, criaturas que sofrerem qualquer dano decorrente de seus feitiços de ataque sofrem 1d6 de dano extra. Desencadeada . Quando conjurar um feitiço de ataque que causa dano, você pode usar uma ação desencadeada para conjurar este feitiço, que termina no final da rodada. Se o alvo sofrer dano do seu feitiço, ele sofre 2d6 de dano extra."},{"id":"destruicao-corroer","nome":"Corroer","tipo":"Ataque","trad":"Destruição","grau":2,"texto":"Alvo: Uma criatura com corpo físico a curta distância em seu campo de visão Você sofre 3 pontos de dano. Faça uma rolagem de ataque de Vontade contra a Agilidade do alvo. Em caso de sucesso, o alvo fica debilitado por 1 minuto. Ao final de cada rodada que estiver debilitado dessa maneira, o alvo sofre 1d6 de dano. Rolagem de Ataque 20+ O alvo sofre 1d6 de dano extra ao final de cada rodada enquanto estiver debilitado dessa maneira."},{"id":"destruicao-detonar","nome":"Detonar","tipo":"Ataque","trad":"Destruição","grau":3,"texto":"Alvo: Um objeto inanimado (isto é, que nunca foi uma criatura) de Tamanho 1 ou menor a média distância em seu campo de visão Você sofre 4 pontos de dano. O alvo sofre uma quantidade de dano igual à sua Vida e então explode, lançando seus restos em um raio de 4 metros a partir de um ponto dentro de seu espaço, e causando 6d6 de dano a tudo o que estiver na área. Uma criatura dentro da área que conseguir um sucesso em uma rolagem de desafio de Agilidade sofre metade do dano."},{"id":"destruicao-evaporar","nome":"Evaporar","tipo":"Ataque","trad":"Destruição","grau":3,"texto":"Alvo: Uma criatura com corpo físico ou um objeto ao seu alcance Você sofre 4 pontos de dano. Faça uma rolagem de ataque de Vontade contra a Agilidade do alvo. Em caso de sucesso, o alvo começa a evaporar e sofre 6d6 de dano. Um objeto destruído por esse tipo de dano se dissolve em uma névoa fina. Uma criatura incapacitada por esse dano morre instantaneamente e se dissolve em uma nuvem carmesim, que obscurece parcialmente o espaço que ocupava por 1 rodada. Rolagem de Ataque 20+ O alvo sofre 2d6 de dano extra."},{"id":"destruicao-destruir","nome":"Destruir","tipo":"Ataque","trad":"Destruição","grau":4,"texto":"Alvo: Um objeto de Tamanho 3 ou menor a média distância em seu campo de visão Você sofre 5 pontos de dano. O alvo sofre 30 pontos de dano."},{"id":"destruicao-desintegrar","nome":"Desintegrar","tipo":"Ataque","trad":"Destruição","grau":5,"texto":"Alvo: Uma criatura com corpo físico ou um objeto a longa distância em seu campo de visão Você sofre 6 pontos de dano. Faça uma rolagem de ataque de Vontade contra a Agilidade do alvo. Em caso de sucesso, o alvo sofre 9d6 de dano. Uma criatura incapacitada por esse dano morre imediatamente, reduzida a um pequena pilha de pó, que se acumula no espaço que ela ocupava anteriormente. Rolagem de Ataque 20+ O alvo sofre 3d6 de dano extra."},{"id":"encantamento-enfeiticar","nome":"Enfeitiçar","tipo":"Ataque","trad":"Encantamento","grau":0,"texto":"Alvo: Uma criatura em seu campo de visão que esteja a longa distância Faça uma rolagem de ataque de Intelecto contra a Intelecto da criatura. Em caso de sucesso, o alvo é movido uma distância de até o valor da Velocidade dele. Rolagem de Ataque 20+ Você recupera a conjuração deste feitiço."},{"id":"encantamento-presenca","nome":"Presença","tipo":"Utilitário","trad":"Encantamento","grau":0,"texto":"Duração: 1 minuto Durante o período de duração do feitiço, criaturas que normalmente são atraídas por membros da sua raça atacam você com 1 revés."},{"id":"encantamento-comandar","nome":"Comandar","tipo":"Ataque","trad":"Encantamento","grau":1,"texto":"Alvo: Uma criatura a curta distância que possa ouvi-lo Faça uma rolagem de ataque de Intelecto contra a Vontade do alvo. Se o alvo estiver encantado, você faz essa rolagem com 1 dádiva. Com um sucesso, o alvo fica compelido por 1 rodada. Rolagem de Ataque 20+ Você recupera a conjuração deste feitiço."},{"id":"encantamento-encantar","nome":"Encantar","tipo":"Ataque","trad":"Encantamento","grau":1,"texto":"Alvo: Uma criatura a curta distância que vê-lo Faça uma rolagem de ataque de Intelecto contra a Vontade do alvo. Se você, ou os membros do seu grupo, atacaram o alvo desde a última vez em que completaram um descanso, você sofre 1 revés. Com um sucesso, o alvo fica encantado por 1 hora ou até sofrer dano. Rolagem de Ataque 20+ Em vez disso, o alvo fica encantado por 1d6 horas ou até sofrer dano."},{"id":"encantamento-questionar","nome":"Questionar","tipo":"Ataque","trad":"Encantamento","grau":1,"texto":"Alvo: Uma criatura a curta distância que possa vê-lo, ouvi-lo e entendê-lo Você faz uma pergunta ao alvo e uma rolagem de ataque de Intelecto contra a Vontade do alvo. Em caso de sucesso, o alvo deve responder com sinceridade e da melhor maneira possível, de acordo com o que ele sabe. Rolagem de Ataque 20+ O alvo fica amedrontado por 1 rodada."},{"id":"encantamento-cativeiro-mental","nome":"Cativeiro Mental","tipo":"Ataque","trad":"Encantamento","grau":2,"texto":"Alvo: Uma criatura a média distância que possa vê-lo e ouvi-lo Faça uma rolagem de ataque de Intelecto contra a Vontade do alvo. Se você, ou os membros do seu grupo, atacaram o alvo desde a última vez em que completaram um descanso, você sofre 1 revés. Com um sucesso, o alvo fica aturdido por 1 minuto ou até sofrer dano. Enquanto o alvo estiver aturdido dessa maneira, você recebe 1 dádiva nas rolagens de ataque para interagir socialmente com ele. Rolagem de Ataque 20+ O alvo fica atordoado enquanto está aturdido dessa maneira."},{"id":"encantamento-compelir","nome":"Compelir","tipo":"Ataque","trad":"Encantamento","grau":2,"texto":"Alvo: Uma criatura a média distância que possa vê-lo Faça uma rolagem de ataque de Intelecto contra a Vontade do alvo. Se você, ou os membros do seu grupo, atacaram o alvo desde a última vez em que completaram um descanso, você sofre 1 revés. Com um sucesso, o alvo fica compelido por 1 minuto, ou até sofrer dano. Rolagem de Ataque 20+ O alvo fica compelido por 1 hora ou até sofrer dano."},{"id":"encantamento-acovardar","nome":"Acovardar","tipo":"Ataque","trad":"Encantamento","grau":3,"texto":"Alvo: Uma criatura a média distância Faça uma rolagem de ataque de Intelecto contra a Vontade do alvo. Com um sucesso, o alvo fica imobilizado por 1 minuto; enquanto estiver imobilizado, ele também fica amedrontado. Uma vez por rodada, quando o alvo sofre dano, ele pode fazer uma rolagem de desafio de Vontade e, em caso de sucesso, remove a aflição imobilização. Rolagem de Ataque 20+ O alvo também fica prostrado e não consegue se levantar enquanto estiver imobilizado."},{"id":"encantamento-implantar-sugestao","nome":"Implantar Sugestão","tipo":"Ataque","trad":"Encantamento","grau":3,"texto":"Alvo: Uma criatura a curta distância que possa vê-lo e ouvi-lo Duração: Concentração, até 1 minuto; veja o efeito Faça uma rolagem de ataque de Intelecto contra a Vontade do alvo. Em caso de sucesso, o alvo fica atordoado pela duração do feitiço ou até sofrer qualquer dano. Se você se concentrar por 1 minuto completo, descreva uma ação a ser realizada que não seja obviamente suicida e que possa ser resumida em uma ou duas frases. Em seguida, descreva o que desencadeia essa ação, como chegar a um destino específico ou ouvir uma palavra ou frase. Se a ação sugerida puder causar prejuízo ao próprio alvo, a seus entes queridos ou à sua propriedade, o alvo pode fazer uma rolagem de desafio de Vontade e, em caso de sucesso, não é afetado. Caso contrário, deverá executar a ação descrita se o acionamento ocorrer a qualquer momento dentro das próximas 8 horas. Assim que o alvo concluir a ação, o efeito termina."},{"id":"encantamento-fascinar","nome":"Fascinar","tipo":"Ataque","trad":"Encantamento","grau":4,"texto":"Alvo: Qualquer quantidade de criaturas a curta distância Cada alvo deve fazer uma rolagem de desafio de Vontade com 1 revés. Se fracassar, ele fica encantado até que você o ataque ou até que você complete um período de descanso. Enquanto estiver encantado dessa maneira, a criatura fica debilitada se estiver além da sua curta distância."},{"id":"encantamento-escravizar","nome":"Escravizar","tipo":"Ataque","trad":"Encantamento","grau":5,"texto":"Alvo: Uma criatura ou objeto a média distância Faça uma rolagem de ataque de Intelecto contra a Vontade do alvo. Se você, ou os membros do seu grupo, atacaram o alvo desde a última vez em que completaram um descanso, você sofre 1 revés. Com um sucesso, o alvo fica encantado. O alvo não envelhece enquanto estiver encantado desta maneira. Ao sofrer dano, ele pode fazer uma rolagem de desafio de Vontade, removendo a aflição se obtiver um sucesso. Enquanto o alvo estiver encantado desta maneira e a longa distância de você, é possível usar uma ação para fazer uma rolagem de ataque de Intelecto contra a Vontade dele. Com um sucesso, ele fica compelido por 1 minuto. Rolagem de Ataque 20+ Se o total da rolagem de ataque inicial for 20 ou mais, e exceder o número-alvo em 5, você realiza as rolagens de ataque de Vontade secundárias contra o alvo encantado com 2 dádivas."},{"id":"fogo-controlar-chamas","nome":"Controlar Chamas","tipo":"Utilitário","trad":"Fogo","grau":0,"texto":"Alvo: Um objeto de Tamanho 1 ou menor a curta distância Você pode atear fogo a um alvo ou, se ele já estiver pegando fogo, apagar suas chamas."},{"id":"fogo-missil-flamejante","nome":"Míssil Flamejante","tipo":"Ataque","trad":"Fogo","grau":0,"texto":"Alvo: Uma criatura ou objeto a longa distância Você lança um míssil incendiário contra o alvo. Faça uma rolagem de ataque de Vontade contra a Agilidade do alvo. Em caso de sucesso, o alvo sofre 1d6 de dano. Rolagem de Ataque 20+ O alvo sofre 1d6 de dano extra."},{"id":"fogo-explosao-flamejante","nome":"Explosão Flamejante","tipo":"Ataque","trad":"Fogo","grau":1,"texto":"Área: Um cone, com 3 metros de comprimento, com origem em um ponto ao seu alcance Chamas irrompem de sua mão, causando 3d6 de dano a tudo que está na área. Cada criatura na área que obtiver sucesso em uma rolagem de desafio de Agilidade sofre metade do dano."},{"id":"fogo-meteoro","nome":"Meteoro","tipo":"Ataque","trad":"Fogo","grau":1,"texto":"Alvo: Um ponto no espaço a média distância Você arremessa uma pedra flamejante contra o alvo. Ao atingilo, ou se colidir com uma criatura ou objeto sólido antes do alvo, ela explode. Chamas se espalham por uma esfera com 1 metro de raio centrada no alvo, ou em um ponto no espaço da criatura ou do objeto, causando 2d6+2 de dano a tudo que está na área. Cada criatura na área que obtiver sucesso em uma rolagem de desafio de Agilidade sofre metade do dano."},{"id":"fogo-protecao-contra-as-chamas","nome":"Proteção Contra As Chamas","tipo":"Utilitário","trad":"Fogo","grau":1,"texto":"Alvo: Uma criatura ao seu alcance Duração: 1 hora Você toca o alvo. Durante esse período, ele sofre metade do dano de fogo."},{"id":"fogo-rajada-ardente","nome":"Rajada Ardente","tipo":"Ataque","trad":"Fogo","grau":2,"texto":"Alvo: Até três criaturas ou objetos a média distância Você lança três mísseis incendiários, que podem ser divididos entre os alvos escolhidos por você. Faça uma rolagem de ataque de Vontade contra a Agilidade do alvo. Em caso de sucesso, o alvo sofre 1d6+1 de dano. Rolagem de Ataque 20+ O alvo sofre 1d3 de dano extra."},{"id":"fogo-manto-flamejante","nome":"Manto Flamejante","tipo":"Utilitário","trad":"Fogo","grau":2,"texto":"Duração: 1 minuto As chamas o envolvem durante todo o tempo, emitindo luz intensa num raio de 10 metros ao seu redor. As chamas são quentes, mas não causam dano a você ou nada que você esteja vestindo ou carregando. Enquanto o efeito durar, você sofre metade do dano causado pelo frio e não fica fatigado devido à exposição a baixas temperaturas. Além disso, quando uma criatura toca em você, ou obtém sucesso em uma rolagem de ataque contra você usando uma arma corpo a corpo, ela sofre 1d6 de dano de fogo."},{"id":"fogo-bola-de-fogo","nome":"Bola de Fogo","tipo":"Ataque","trad":"Fogo","grau":3,"texto":"Alvo: Um ponto no espaço a longa distância Você arremessa uma esfera de fogo. Ao atingi-lo, ou se colidir com uma criatura ou objeto sólido antes do alvo, ela explode. Chamas se espalham por uma esfera de 5 metros de raio centrada no alvo ou em um ponto no espaço da criatura ou do objeto, causando 5d6 de dano a tudo na área. Cada criatura na área que obtiver sucesso em uma rolagem de desafio de Agilidade sofre metade do dano."},{"id":"fogo-imolar","nome":"Imolar","tipo":"Ataque","trad":"Fogo","grau":3,"texto":"Alvo: Uma criatura ou objeto a média distância O alvo começa a fumegar e pode sofrer combustão espontânea. Faça uma rolagem de ataque de Vontade contra a Agilidade do alvo. Em caso de sucesso, o alvo sofre 4d6 de dano e pega fogo. Rolagem de Ataque 20+ O alvo sofre 2d6 de dano extra."},{"id":"fogo-muralha-de-chamas","nome":"Muralha de Chamas","tipo":"Ataque","trad":"Fogo","grau":4,"texto":"Área: Uma linha moldável de 10 metros de comprimento, 5 metros de altura e 1 metro de largura, com origem em um ponto a longa distância Duração: 1 minuto As chamas preenchem a área pela duração do feitiço, obscurecendo parcialmente tudo o que está dentro e atrás dela. Criaturas ou objetos que estão na área quando você conjura o feitiço, ou que entram nela posteriormente, sofrem 3d6 de dano. Ao final de cada rodada pela duração do feitiço, cada criatura e objeto inflamável na área sofrem 3d6 de dano, e cada um que estiver a curta distância da borda da área sofre 1d6 de dano, a menos que obtenha sucesso em uma rolagem de desafio de Força."},{"id":"fogo-vincular-genio-das-chamas","nome":"Vincular Gênio das Chamas","tipo":"Utilitário","trad":"Fogo","grau":5,"texto":"Alvo: Um cubo de fogo, com 2 metros de lado, com origem em um ponto a longa distância Duração: 1 minuto Ao final da rodada em que você conjura este feitiço, o alvo se transforma em um gênio das chamas de Tamanho 2. Você não pode encerrar este feitiço voluntariamente. Quando o gênio surgir, faça uma rolagem de ataque de Vontade contra a Vontade dele. Em caso de sucesso, o gênio fica compelido enquanto o efeito durar; se fracassar, ele se torna hostil a você."},{"id":"ilusao-alarido","nome":"Alarido","tipo":"Utilitário","trad":"Ilusão","grau":0,"texto":"Alvo: Um ponto no espaço a média distância Duração: 1 minuto O ponto alvo emite um som que escolhido por você pela duração do feitiço. Isso pode ser ruído qualquer ou frase dita em um idioma que você conheça, e o volume pode variar de um sussurro até um estrondo tão alto quanto um trovão. Enquanto o efeito durar, você pode alterar o som livremente, simulando efeitos como o choque de lâminas, uma conversa ou o som de passos se aproximando ou se afastando."},{"id":"ilusao-disfarce","nome":"Disfarce","tipo":"Utilitário","trad":"Ilusão","grau":0,"texto":"Alvo: Uma criatura ao seu alcance Duração: 1 hora Você toca o alvo, criando um disfarce ilusório que permanece pela duração do feitiço. Você determina a aparência do disfarce. É possível aumentar ou diminuir a altura, ou o peso aparente, do alvo em até 25%. Também é possível alterar a aparência das roupas e equipamentos do alvo, embora o efeito não encubra quaisquer sons que ele emite normalmente."},{"id":"ilusao-imagem-fantasma","nome":"Imagem Fantasma","tipo":"Utilitário","trad":"Ilusão","grau":1,"texto":"Área: Um cubo com 2 metros de lado, com origem em um ponto em seu campo de visão a curta distância Duração: 1 hora; veja o efeito Uma ilusão visual silenciosa de uma criatura, objeto ou força surge na área. Se você criar a ilusão de uma criatura, ela se move e se comporta de maneira convincente pela duração do feitiço. Se a ilusão for atacada, ou se você não conseguir vê-la ao final da rodada, o efeito termina imediatamente."},{"id":"ilusao-jogo-da-troca","nome":"Jogo da Troca","tipo":"Utilitário","trad":"Ilusão","grau":1,"texto":"Duração: 1 hora; veja o efeito Quatro duplicatas ilusórias surgem em espaços desocupados ao seu alcance. Enquanto o efeito durar, cada duplicata se move com você, trocando de lugar continuamente, de modo que quem estiver lhe observando não consiga discernir qual delas é você. O movimento dos duplicados não desencadeia ataques livres. Quando uma criatura obtiver sucesso em uma rolagem de ataque contra sua Defesa, Força ou Agilidade, role um d20 para determinar se o ataque afeta você ou uma das duplicatas. Se atingir uma duplicata, reduza a quantidade de duplicatas em um. O efeito termina quando a última duplicata desaparecer."},{"id":"ilusao-vertigem","nome":"Vertigem","tipo":"Ataque","trad":"Ilusão","grau":1,"texto":"Alvo: Uma criatura viva a curta distância O alvo tem a sensação de que tudo ao seu redor está girando. Faça uma rolagem de ataque de Intelecto contra a Percepção do alvo. Em caso de sucesso, o alvo é acometido por uma vertigem durante 1 minuto. Se a criatura se mover mais de 2 metros no turno dela enquanto estiver afetada dessa maneira, ela deve fazer uma rolagem de desafio de Agilidade. Se fracassar, fica prostrada e seu turno se encerra. Rolagem de Ataque 20+ Enquanto estiver com vertigem, o alvo também fica prostrado ao sofrer dano."},{"id":"ilusao-invisibilidade","nome":"Invisibilidade","tipo":"Utilitário","trad":"Ilusão","grau":2,"texto":"Alvo: Uma criatura ou objeto ao seu alcance Duração: 1 minuto Você toca o alvo, que se torna invisível pela duração do feitiço."},{"id":"ilusao-veu-sensorial","nome":"Véu Sensorial","tipo":"Utilitário","trad":"Ilusão","grau":2,"texto":"Área: Um cubo com 2 metros de lado, com origem em um ponto em seu campo de visão a curta distância Duração: 1 hora; veja o efeito Uma ilusão visual e auditiva de uma criatura, objeto ou força surge na área. Se, ao final da rodada, você não puder ver a ilusão, o efeito termina imediatamente. Se você criar a ilusão de uma força perigosa, como fogo ou água fervente, qualquer criatura que entrar no espaço da ilusão deve fazer uma rolagem de desafio de Percepção. Em caso de fracasso, sofre 2d6 de dano. Se você criar a ilusão de uma criatura, ela se move e se comporta de maneira realista e usa seu valor de Intelecto para seus atributos, Defesa e Vida. Ela ignora todas as aflições e desaparece quando fica incapacitada, encerrando efeito. Enquanto o efeito durar, é possível usar uma ação para mover a ilusão em até 10 metros e fazer com que ela ataque uma criatura a até 1 metro dela, desde que a criatura possa ver a ilusão e acredite que seja real. Faça uma rolagem de ataque de Intelecto contra a Percepção do alvo. Em caso de sucesso, o alvo acredita ter sido ferido, queimado ou afetado de alguma outra maneira pela ilusão e sofre 2d6 de dano. Rolagem de Ataque 20+ O alvo sofre 2d6 de dano extra."},{"id":"ilusao-chamariz","nome":"Chamariz","tipo":"Utilitário","trad":"Ilusão","grau":3,"texto":"Desencadeada: Você pode usar uma ação desencadeada para conjurar este feitiço quando uma criatura obtiver sucesso em uma rolagem de ataque contra você. O sucesso é convertido em fracasso e você se teletransporta para um espaço desocupado à sua escolha a curta distância."},{"id":"ilusao-fantasmagoria","nome":"Fantasmagoria","tipo":"Utilitário","trad":"Ilusão","grau":3,"texto":"Área: Um cubo com 4 metros de lado, com origem em um ponto em seu campo de visão a longa distância Duração: 1 hora; ver o efeito Uma ilusão de uma criatura, objeto ou força surge na área, aparentando ser real em aparência, som e demais sensações perceptíveis. Se, ao final da rodada, você não puder ver a ilusão, o efeito termina imediatamente. Se você criar a ilusão de uma força perigosa, como fogo ou água fervente, qualquer criatura que entrar no espaço da ilusão deve fazer uma rolagem de desafio de Percepção. Em caso de fracasso, sofre 3d6 de dano. Se você criar a ilusão de uma criatura, ela se move e se comporta de maneira realista e usa seu valor de Intelecto para seus atributos, Defesa e Vida. Ela ignora todas as aflições e desaparece quando fica incapacitada, encerrando efeito. Enquanto o efeito durar, é possível usar uma ação para mover a ilusão em até 10 metros e fazer com que ela ataque uma criatura a até 1 metro dela, desde que a criatura possa ver a ilusão e acredite que seja real. Faça uma rolagem de ataque de Intelecto contra a Percepção do alvo. Em caso sucesso, o alvo acredita ter sido ferido, queimado ou afetado de alguma outra maneira pela ilusão e sofre 4d6 de dano. Rolagem de Ataque 20+ O alvo sofre 2d6 de dano extra."},{"id":"ilusao-miragem","nome":"Miragem","tipo":"Utilitário","trad":"Ilusão","grau":4,"texto":"Área: Um cilindro com 5 metros de altura e 10 metros de raio, centralizado em um ponto a longa distância Duração: Até você completar um descanso. Um terreno ilusório surge dentro da área e permanece pela duração do feitiço, aparentando ser real em aparência, som, cheiro e demais sensações perceptíveis. Você pode alterar completamente a aparência de um terreno real ou incorporar suas características à ilusão. A ilusão pode ocultar completamente qualquer característica do terreno real em sua área e esconder seus efeitos visuais. Por exemplo, você pode tornar o fogo invisível e ocultar completamente a luz que ele projeta, embora ele ainda gere calor e cause dano às criaturas que entrem em contato com ele. Sacrifício Você pode gastar uma conjuração deste feitiço para usar fantasmagoria . Permanência Se você lançar este feitiço na mesma área todos os dias durante um mês e um dia, o efeito se torna permanente."},{"id":"ilusao-menecma","nome":"Menecma","tipo":"Utilitário","trad":"Ilusão","grau":5,"texto":"Área: Um cubo grande o suficiente para acomodar uma criatura do seu Tamanho, com origem em um ponto a curta distância Duração: 1 hora; ver o efeito Uma cópia ilusória de si mesmo surge dentro da área. A cópia é idêntica a você em todos os aspectos como, por exemplo, aparência e voz. Ela tem os mesmos atributos e características que você. Entretanto, ela ignora todas as aflições e desaparece quando fica incapacitada, encerrando efeito. Ao se mover, você também pode mover sua cópia até sua Velocidade máxima, em qualquer direção e da maneira exata que você normalmente se move. Você pode optar por lançar feitiços do seu próprio espaço ou do espaço ocupado pela sua cópia."},{"id":"maldicao-agouro","nome":"Agouro","tipo":"Ataque","trad":"Maldição","grau":0,"texto":"Alvo: Uma criatura a curta distância que vê-lo Faça uma rolagem de ataque de Intelecto contra a Vontade do alvo. Com um sucesso, o alvo fica amaldiçoado por 1 minuto ou até sofrer dano. Enquanto estiver amaldiçoado, o alvo fica debilitado e você faz rolagens de ataque contra ele com 1 dádiva. Rolagem de Ataque 20+ O alvo também fica aturdido por 1 rodada."},{"id":"maldicao-peste","nome":"Peste","tipo":"Ataque","trad":"Maldição","grau":0,"texto":"Alvo: Uma criatura viva a curta distância Faça uma rolagem de ataque de Intelecto contra a Força do alvo. Com um sucesso, o corpo do alvo fica coberto de bolhas verdes e purulentas. O alvo sofre 1d3 de dano da peste e fica amedrontado por 1 rodada. Rolagem de Ataque 20+ O alvo fica amedrontado por 1 minuto."},{"id":"maldicao-amedrontar","nome":"Amedrontar","tipo":"Ataque","trad":"Maldição","grau":1,"texto":"Alvo: Uma criatura a curta distância que vê-lo Faça uma rolagem de ataque de Intelecto contra a Vontade do alvo. Com um sucesso, o alvo fica amedrontado por 1 minuto. Enquanto estiver amedrontado, o alvo pode usar uma ação para fazer uma rolagem de desafio de Vontade e remover essa aflição com um sucesso. Rolagem de Ataque 20+ Enquanto estiver amedrontado dessa maneira, o alvo também fica debilitado."},{"id":"maldicao-coxo","nome":"Coxo","tipo":"Ataque","trad":"Maldição","grau":1,"texto":"Alvo: Uma criatura viva a curta distância Faça uma rolagem de ataque de Intelecto contra a Força do alvo. Com um sucesso, o alvo fica lento por 1 minuto. Rolagem de Ataque 20+ O alvo também fica prostrado e não consegue se levantar enquanto estiver sofrendo com a aflição lento."},{"id":"maldicao-dor","nome":"Dor","tipo":"Ataque","trad":"Maldição","grau":1,"texto":"Alvo: Uma criatura viva a curta distância Faça uma rolagem de ataque de Intelecto contra a Força do alvo. Com um sucesso, durante 1 minuto, sempre que o alvo sofrer dano, ele sofre 1d6 de dano extra. Rolagem de Ataque 20+ Além disso, durante 1 minuto, sempre que o alvo sofrer dano, ele fica aturdido por 1 rodada."},{"id":"maldicao-fraqueza","nome":"Fraqueza","tipo":"Ataque","trad":"Maldição","grau":2,"texto":"Alvo: Uma criatura ou objeto a média distância Faça uma rolagem de ataque de Intelecto contra a Força do alvo. Com um sucesso, o alvo fica amaldiçoado por 1 minuto. Enquanto estiver amaldiçoado, o alvo sofre uma penalidade de –10 em Vida e faz rolagens de ataque e de desafio de Força e Agilidade com 1 revés. Rolagem de Ataque 20+ A maldição dura até você morrer ou até decidir removê-la."},{"id":"maldicao-vulnerabilidade","nome":"Vulnerabilidade","tipo":"Ataque","trad":"Maldição","grau":2,"texto":"Alvo: Uma criatura ou objeto a média distância Faça uma rolagem de ataque de Intelecto contra a Força do alvo. Com um sucesso, o alvo fica amaldiçoado por 1 minuto. Enquanto estiver amaldiçoado, ataques contra o alvo são feitos com 1 dádiva, e ele faz rolagens de desafio com 1 revés para resistir aos ataques. Rolagem de Ataque 20+ A maldição dura até você morrer ou até decidir removê-la."},{"id":"maldicao-pavor","nome":"Pavor","tipo":"Ataque","trad":"Maldição","grau":3,"texto":"Área: Um cone, com 10 metros de comprimento, com origem em um ponto ao seu alcance Uma onda de terror se espalha por toda a área. Cada criatura dentro da área deve fazer uma rolagem de desafio de Vontade e, se fracassar, fica amedrontada por 1 minuto. Enquanto estiver amedrontada dessa maneira, a criatura só pode fazer turnos rápidos a cada rodada, usando uma ação para fugir de você pela rota mais segura que estiver disponível. Ao final de cada rodada, se não houver um caminho desobstruído até você e a criatura não puder vê-lo, ela poderá fazer uma rolagem de desafio de Vontade e remover essa aflição com um sucesso."},{"id":"maldicao-suino","nome":"Suíno","tipo":"Ataque","trad":"Maldição","grau":3,"texto":"Alvo: Até três criaturas vivas em seu campo de visão a média distância Duração: 1 minuto; veja o efeito Cada alvo deve fazer uma rolagem de desafio de Força. Se fracassar, é transformado em um porco (um animal pequeno ) pela duração do feitiço, juntamente com suas vestes e tudo o que carrega consigo. Enquanto estiver transformado em suíno, a criatura fica amedrontada e só pode fazer turnos rápidos a cada rodada, usando sua ação para fugir de você pela rota mais segura que estiver disponível. O efeito se encerra imediatamente quando o alvo sofre dano."},{"id":"maldicao-sapo","nome":"Sapo","tipo":"Ataque","trad":"Maldição","grau":4,"texto":"Alvo: Uma criatura viva em seu campo de visão a média distância Duração: Concentração, até 1 minuto; veja o efeito Faça uma rolagem de ataque de Intelecto contra a Força do alvo; você recebe 3 dádivas na rolagem se o alvo tiver 40 de Vida ou menos. Em caso de sucesso, o alvo se transforma em um sapo inofensivo (um animal minúsculo ), permanecendo nessa forma enquanto você estiver concentrado, por até 1 minuto. Se mantiver sua concentração ininterruptamente por toda a duração do feitiço, a maldição se torna permanente até você morrer ou decidir removê-la. A maldição também termina se uma virgem beijar o alvo por livre e espontânea vontade. Rolagem de Ataque 20+ A maldição dura automaticamente até você morrer ou até usar uma ação para removê-la enquanto a criatura estiver a média distância."},{"id":"maldicao-petrificar","nome":"Petrificar","tipo":"Ataque","trad":"Maldição","grau":5,"texto":"Alvo: Uma criatura ou objeto a média distância que possua um corpo físico Faça uma rolagem de ataque de Intelecto contra a Força do alvo; você recebe 3 dádivas na rolagem se o alvo tiver 50 de Vida ou menos. Com um sucesso, o alvo sofre 7d6+10 de dano e fica lento por 1 minuto. Se o alvo ficar incapacitado por esse dano, ele se transforma em uma estátua de pedra e morre instantaneamente. Rolagem de Ataque 20+ O alvo sofre 3d6 de dano extra."},{"id":"natureza-bolotas-magicas","nome":"Bolotas Mágicas","tipo":"Ataque","trad":"Natureza","grau":0,"texto":"Alvo: Até cinco bolotas, castanhas ou sementes ao seu alcance Duração: 1 hora; ver o efeito Você toca os alvos, imbuindo cada um com magia pela duração do feitiço ou até que uma criatura os utilize para atacar. Uma criatura ataca com uma bolota ao arremessá-la contra uma criatura ou objeto a curta distância, fazendo uma rolagem de ataque de Agilidade contra a Agilidade do alvo. Em caso de sucesso, o alvo do ataque sofre 1d3 de dano e fica lento por 1 rodada. Se esse dano o incapacitar, ele cria raízes no solo e se transforma permanentemente em uma muda. Rolagem de Ataque 20+ O alvo sofre 1d6 de dano extra."},{"id":"natureza-pele-de-carvalho","nome":"Pele de Carvalho","tipo":"Utilitário","trad":"Natureza","grau":0,"texto":"Duração: 1 hora Enquanto o efeito durar, você recebe um bônus de +2 em Defesa, e, ao tentar se esconder em um ambiente de floresta, você faz a rolagem de desafio de Agilidade com 1 dádiva."},{"id":"natureza-bagas-curativas","nome":"Bagas Curativas","tipo":"Utilitário","trad":"Natureza","grau":1,"texto":"Alvo: Até três bagas frescas ao seu alcance Duração: 8 horas; veja o efeito Você toca os alvos, imbuindo cada um com magia pela duração do feitiço ou até que uma criatura os consuma. Uma criatura viva pode usar uma ação para consumir uma baga curativa, curando dano igual à metade da sua própria taxa de cura."},{"id":"natureza-bastao-de-abrunheiro","nome":"Bastão de Abrunheiro","tipo":"Utilitário","trad":"Natureza","grau":1,"texto":"Alvo: Uma clava ou cajado que está em suas mãos Duração: 1 hora; ver o efeito Você imbui a clava ou cajado com magia, e a arma permanece pela duração do feitiço ou até você soltá-la. Enquanto empunhar a arma, você recebe +2 em Velocidade, e seus ataques com ela causam 1d6 de dano extra."},{"id":"natureza-crescimento-exuberante","nome":"Crescimento Exuberante","tipo":"Utilitário","trad":"Natureza","grau":1,"texto":"Área: Um círculo no chão com raio de 10 metros centralizado em um ponto a média distância Duração: 1 hora Trepadeiras e ervas daninhas se espalham por toda a área, que conta como terreno difícil pela duração do feitiço. Quando o efeito termina, toda a vegetação afetada por este feitiço murcha e morre."},{"id":"natureza-cipos-constritores","nome":"Cipós Constritores","tipo":"Ataque","trad":"Natureza","grau":2,"texto":"Alvo: Até cinco criaturas ou objetos a média distância Cipós brotam do chão sob os alvos. Cada alvo deve obter sucesso em uma rolagem de Agilidade ou ficará imobilizado por 1 minuto. O alvo pode usar uma ação para arrancar o cipó e, assim, remover a aflição."},{"id":"natureza-pinhas-flamejantes","nome":"Pinhas Flamejantes","tipo":"Ataque","trad":"Natureza","grau":2,"texto":"Alvo: Até cinco pinhas, castanhas ou sementes ao seu alcance Duração: 8 horas; veja o efeito Você toca os alvos, imbuindo cada um com magia pela duração do feitiço ou até que uma criatura os utilize para atacar. Um objeto imbuído emite luz em 5 metros de raio ao seu redor. Uma criatura ataca com uma pinha ao arremessá-la contra uma criatura ou objeto a média distância, fazendo uma rolagem de ataque de Agilidade contra a Agilidade do alvo. Com um sucesso, o alvo do ataque sofre 1d6 de dano, e tudo que estiver a 1 metro dele sofre 1d3 de dano devido às fagulhas lançadas pelo impacto. Rolagem de Ataque 20+ O alvo do ataque sofre 1d6 de dano extra."},{"id":"natureza-caminhada-florestal","nome":"Caminhada Florestal","tipo":"Utilitário","trad":"Natureza","grau":3,"texto":"Duração: 1 minuto Você e tudo o que veste e carrega tornam-se verde-brilhante pela duração do feitiço. Durante esse tempo, você pode entrar no espaço ocupado por uma planta do seu Tamanho ou maior e sair instantaneamente em um espaço desocupado a partir de outra planta do mesmo porte que esteja a média distância."},{"id":"natureza-espinheiro","nome":"Espinheiro","tipo":"Utilitário","trad":"Natureza","grau":3,"texto":"Área: Um círculo no chão com raio de 10 metros centralizado em um ponto a média distância Duração: 1 minuto Vários arbustos com espinhos longos e aguçados se espalham pela área, que se transforma em terreno difícil pela duração do feitiço. Quando o efeito termina, os arbustos murcham e morrem. Qualquer criatura que entrar na área ou se mover através ela deve fazer uma rolagem de desafio de Agilidade com 1 revés, sofrendo 1d6 de dano se fracassar."},{"id":"natureza-ira-da-natureza","nome":"Ira da Natureza","tipo":"Ataque","trad":"Natureza","grau":4,"texto":"Alvo: Até cinco criaturas ou objetos a média distância Cipós semelhantes a chicotes saltam e causam 3d6 de dano a cada alvo, que deve fazer uma rolagem de desafio de Agilidade. Se fracassar, o alvo é movido por 6 metros em uma direção escolhida por você e fica imobilizado por 1 minuto. O alvo pode usar uma ação para fazer uma rolagem de desafio de Força com 1 revés; em caso de sucesso, a aflição é removida."},{"id":"natureza-forma-do-guardiao-de-carvalho","nome":"Forma do Guardião de Carvalho","tipo":"Utilitário","trad":"Natureza","grau":5,"texto":"Duração: 1 minuto Você se transforma em uma poderosa árvore animada. Enquanto o efeito durar, você não pode conjurar feitiços, mas obtém os seguintes benefícios: • Você recebe um bônus de +3 em Defesa, +15 de Vida e dobra o seu Tamanho. • Você faz rolagens de ataque e desafio de Força com 1 dádiva. • Seus galhos são considerados armas corpo a corpo que causam 3d6 de dano. • É possível usar uma ação desencadeada no seu turno para gastar a conjuração este feitiço de Natureza. Neste caso, você estende a duração desse efeito por uma quantidade de minutos igual ao grau do feitiço."},{"id":"necromancia-ocultar-se-de-mortos-vivos","nome":"Ocultar-Se de Mortos-Vivos","tipo":"Utilitário","trad":"Necromancia","grau":0,"texto":"Duração: 1 minuto; veja o efeito Você fica escondido de criaturas mortas-vivas pela duração do feitiço. O efeito termina imediatamente se você fizer um ataque."},{"id":"necromancia-preensao-espectral","nome":"Preensão Espectral","tipo":"Ataque","trad":"Necromancia","grau":0,"texto":"Alvo: Uma criatura ou objeto a média distância Uma mão sombria avança em direção ao alvo. Faça uma rolagem de ataque de Intelecto contra a Agilidade dele. Em caso de sucesso, o alvo sofre 1d3 de dano e faz rolagens de ataque com 1 revés por 1 rodada. Rolagem de Ataque 20+ O alvo sofre 1d6 de dano extra."},{"id":"necromancia-animar-cadaver","nome":"Animar Cadáver","tipo":"Utilitário","trad":"Necromancia","grau":1,"texto":"Alvo: Um cadáver de Tamanho 1/2 ou 1 ao seu alcance Você toca o alvo. Se você se concentrar e mantiver contato com o alvo por 1 minuto, ele se tornará um cadáver animado compelido de mesmo Tamanho. Sacrifício Você pode gastar uma conjuração deste feitiço para usar preensão espectral ."},{"id":"necromancia-ceifar-alma","nome":"Ceifar Alma","tipo":"Ataque","trad":"Necromancia","grau":1,"texto":"Alvo: Uma criatura, morta há não mais do que 1 rodada, a curta distância Duração: 4 horas; veja o efeito Uma bola de luz tênue surge de dentro do alvo e voa em sua direção, orbitando seu corpo enquanto durar o feitiço. É possível usar uma ação para encerrar o efeito imediatamente e curar uma quantidade de dano igual à sua taxa de cura. Até o efeito terminar, a criatura alvo não pode ser trazida de volta à vida por nenhuma maneira."},{"id":"necromancia-preensao-sepulcral","nome":"Preensão Sepulcral","tipo":"Ataque","trad":"Necromancia","grau":1,"texto":"Área: Um círculo no chão com raio de 5 metros centralizado em um ponto a curta distância Duração: 1 minuto Enquanto o efeito durar, a escuridão se alastra pela área; garras esqueléticas e mãos pútridas emergem do solo, que se torna terreno difícil. Cada criatura que estiver na área quando você conjurar o feitiço, ou que estiver nela ao final de uma rodada, deve fazer uma rolagem de desafio de Agilidade. Se fracassar, sofre 1d6 de dano e fica imobilizada pela duração do feitiço. Se já estiver imobilizada, sofre 1d6 de dano extra. Uma criatura pode usar uma ação para se libertar, removendo, assim, a aflição imobilizado."},{"id":"necromancia-cranio-estridente","nome":"Crânio Estridente","tipo":"Ataque","trad":"Necromancia","grau":2,"texto":"Alvo: Um ponto no espaço ao seu alcance Duração: 1 minuto; veja o efeito Um crânio humano aparece no ar, centralizado no alvo. Ele possui o traço voador, Defesa 20 e Vida 10. Quando o crânio sofrer uma quantidade de dano igual à Vida dele, ele se desfaz e o efeito termina imediatamente. Ao conjurar o feitiço, você pode fazer o crânio voar até 10 metros e gritar; também é possível fazê-lo usando uma ação ou uma ação desencadeada no seu turno pela duração do feitiço. O ruído se propaga por uma esfera com 3 metros de raio centralizada no crânio. Cada criatura na área que ouvir o grito deve obter sucesso em uma rolagem de desafio de Força ou sofrer 1d6+1 de dano."},{"id":"necromancia-estilhacos-osseos","nome":"Estilhaços Ósseos","tipo":"Ataque","trad":"Necromancia","grau":2,"texto":"Alvo: Uma criatura com estrutura óssea a média distância Faça uma rolagem de ataque de Intelecto contra a Força do alvo. Em caso de sucesso, o alvo sofre 3d6+5 de dano. Se o alvo ficar incapacitado por esse dano ele morre instantaneamente, e os ossos de seu corpo explodem em um cone com 3 metros de comprimento, com origem em um ponto dentro de seu espaço. Tudo o que estiver na área sofre 1d6 de dano; criaturas que conseguirem um sucesso em uma rolagem de desafio de Agilidade não sofrem dano. Rolagem de Ataque 20+ O alvo sofre 2d6 de dano extra."},{"id":"necromancia-canibalizar-magia","nome":"Canibalizar Magia","tipo":"Ataque","trad":"Necromancia","grau":3,"texto":"Alvo: Uma criatura ou objeto a média distância Faça uma rolagem de ataque de Intelecto contra a Força do alvo. Em caso de sucesso, o alvo sofre 3d6 de dano e você recupera a conjuração de um feitiço de grau 1 ou inferior. Rolagem de Ataque 20+ O alvo sofre 2d6 de dano extra e você recupera a conjuração de um feitiço de grau 2 ou inferior."},{"id":"necromancia-poco-do-poder-das-trevas","nome":"Poço do Poder das Trevas","tipo":"Utilitário","trad":"Necromancia","grau":3,"texto":"Área: Um círculo no chão com raio de 5 metros centralizado em um ponto a média distância Duração: 1 minuto Um glifo aparece no ponto de origem. Enquanto o efeito durar, qualquer criatura na área que sofrer dano sofre 2d6 de dano extra."},{"id":"necromancia-selar-os-portoes-do-submundo","nome":"Selar Os Portões do Submundo","tipo":"Ataque","trad":"Necromancia","grau":4,"texto":"Área: Uma esfera com raio de 10 metros centralizada em um ponto a média distância Duração: 1 minuto Tentáculos de energia necromântica se espalham pela área. Enquanto o efeito durar, mortos-vivos dentro da área fazem rolagens de ataque e desafio com 1 dádiva, e criaturas vivas dentro da área, além de você, fazem rolagens de ataque e desafio com 1 revés. Além disso, criaturas vivas de Tamanho 1 ou 1/2 que morrem na área se tornam cadáveres animados compelidos."},{"id":"necromancia-exercito-dos-mortos","nome":"Exército dos Mortos","tipo":"Utilitário","trad":"Necromancia","grau":5,"texto":"Área: Um círculo no chão com raio de 2 metros centralizado em um ponto a média distância Duração: 1 hora A área se torna um terreno difícil pela duração do feitiço. Ao final da rodada na qual você conjurou este feitiço, 2d6 cadáveres animados compelidos se emergem do chão e se levantam. Todos os cadáveres animados criados por este feitiço contam como uma única criatura para determinar quantas criaturas mortasvivas compelidas você pode controlar. O efeito termina quando o último cadáver animado é destruído."},{"id":"primal-esconder-se-de-animais","nome":"Esconder-Se de Animais","tipo":"Utilitário","trad":"Primal","grau":0,"texto":"Duração: 1 minuto; veja o efeito Você fica escondido de todos os animais pela duração do feitiço. O efeito termina imediatamente se você fizer um ataque."},{"id":"primal-fera-interior","nome":"Fera Interior","tipo":"Utilitário","trad":"Primal","grau":0,"texto":"Duração: 1 minuto Seus olhos brilham, seu corpo fica coberto de pelos, suas unhas se alongam e se transformam em garras, e seus dentes se tornam presas. Enquanto o efeito durar, você ganha visão no escuro, um bônus de +2 em Velocidade, e seus ataques com golpes desarmados e armas naturais causam 1d6 de dano extra."},{"id":"primal-cativar-animal","nome":"Cativar Animal","tipo":"Ataque","trad":"Primal","grau":1,"texto":"Alvo: Um animal em seu campo de visão a curta distância Faça uma rolagem de ataque de Vontade contra a Vontade do alvo. Você faz a rolagem de ataque com 1 dádiva se estiver sob o efeito do feitiço língua das feras . Se a Vida do alvo for maior que a sua, o feitiço falha e a conjuração é desperdiçada. Em caso de sucesso, o alvo fica encantado até que você complete um descanso. Ele o acompanha em suas aventuras e o ajuda da melhor maneira possível, embora permaneça sob o controle do MJ. Você pode ter uma quantidade de animais encantados dessa maneira igual ao seu valor de Poder. Se conjurar este feitiço fizer com que você exceda esse limite, o efeito termina automaticamente no animal que estiver encantado há tempo. Rolagem de Ataque 20+ O alvo fica permanentemente encantado."},{"id":"primal-lingua-das-feras","nome":"Língua das Feras","tipo":"Utilitário","trad":"Primal","grau":1,"texto":"Duração: 1 minuto Enquanto o efeito durar, você pode se comunicar com qualquer animal que possa ouvi-lo."},{"id":"primal-convocar-animal-pequeno","nome":"Convocar Animal Pequeno","tipo":"Utilitário","trad":"Primal","grau":1,"texto":"Área: Um cubo com 1 metro de lado, com origem em um ponto a média distância, sobre uma superfície sólida. Duração: 1 hora Um animal pequeno ou animal minúsculo compelido surge na área. Um animal minúsculo pode ter um dos seguintes traços: escalador, nadador, peçonhento ou voador. O animal é de uma espécie apropriada para o ambiente onde o feitiço foi conjurado. Quando o efeito termina ou o animal fica incapacitado, ele retorna ao local de onde veio."},{"id":"primal-convocar-animal-medio","nome":"Convocar Animal Médio","tipo":"Utilitário","trad":"Primal","grau":2,"texto":"Área: Um cubo com 1 metro de lado, com origem em um ponto a média distância, sobre uma superfície sólida. Duração: 1 hora Este feitiço funciona como convocar animal pequeno , exceto que um animal médio , animal pequeno ou animal minúsculo compelido surge dentro da área. Um animal pequeno ou minúsculo pode ter um dos seguintes traços: escalador, nadador, peçonhento ou voador."},{"id":"primal-fera-atroz","nome":"Fera Atroz","tipo":"Utilitário","trad":"Primal","grau":2,"texto":"Alvo: Você ou um animal a curta distância Duração: 1 minuto O alvo se torna uma fera selvagem. Enquanto o efeito durar, o tamanho do alvo aumenta para 1 ou aumenta em mais um se for de Tamanho 1 ou maior; seus ataques com golpes desarmados e armas naturais causam 1d6 de dano extra."},{"id":"primal-convocar-animal-grande","nome":"Convocar Animal Grande","tipo":"Utilitário","trad":"Primal","grau":3,"texto":"Área: Um cubo com 2 metro de lado, com origem em um ponto a média distância, sobre uma superfície sólida. Duração: 1 hora Este feitiço funciona como convocar animal pequeno , exceto que um animal grande , animal médio ou animal pequeno compelido surge na área. Um animal médio ou pequeno pode ter um dos seguintes traços: escalador, nadador, peçonhento ou voador."},{"id":"primal-dar-o-bote","nome":"Dar o Bote","tipo":"Ataque","trad":"Primal","grau":3,"texto":"Requisitos: Você deve estar sob efeito do feitiço fera interior . Você se move até o dobro da sua Velocidade. A qualquer momento durante este movimento, você pode realizar um ataque com um golpe desarmado ou arma natural contra um alvo dentro do seu alcance, usando Vontade no lugar do atributo normalmente utiliza no ataque. Em caso de sucesso, o alvo sofre o dano do ataque mais 4d6 de dano extra e fica prostrado."},{"id":"primal-chamado-selvagem","nome":"Chamado Selvagem","tipo":"Utilitário","trad":"Primal","grau":4,"texto":"Alvo: Até cinco criaturas a curta distância Duração: 1 minuto Os alvos adquirem traços bestiais. Enquanto o efeito durar, cada alvo recebe um bônus de +10 em Vida, um bônus de +2 em Velocidade e causa 1d6 de dano extra com seus ataques feitos com golpes desarmados e armas naturais."},{"id":"primal-convocar-animal-enorme","nome":"Convocar Animal Enorme","tipo":"Utilitário","trad":"Primal","grau":5,"texto":"Área: Um cubo com 3 metros de lado, com origem em um ponto a média distância e apoiado sobre uma superfície sólida Duração: 1 hora Este feitiço funciona como convocar animal pequeno , exceto que um animal enorme , animal grande ou animal médio compelido aparece na área. Um animal grande ou médio pode ter um dos seguintes traços: escalador, nadador, peçonhento ou voador."},{"id":"proibida-lingua-negra","nome":"Língua Negra","tipo":"Utilitário","trad":"Proibida","grau":0,"texto":"Duração: 1 minuto Enquanto o efeito durar, você realiza rolagens de ataque de Intelecto e Vontade com 1 dádiva contra demônios, diabos, espíritos e mortos-vivos."},{"id":"proibida-ferir","nome":"Ferir","tipo":"Ataque","trad":"Proibida","grau":0,"texto":"Alvo: Uma criatura a curta distância em seu campo de visão Farpas invisíveis dilaceram o corpo do alvo. Faça uma rolagem de ataque de Intelecto contra a Força do alvo. Em caso de sucesso, o alvo sofre uma penalidade de –5 em Vida por 1 minuto. Rolagem de Ataque 20+ A penalidade em Vida é de –10."},{"id":"proibida-defecacao-odiosa","nome":"Defecação Odiosa","tipo":"Ataque","trad":"Proibida","grau":1,"texto":"Alvo: Uma criatura viva com corpo físico a média distância As entranhas do alvo se contorcem e roncam ruidosamente. Se a Vida do alvo for 10 ou menos, ele morre instantaneamente, com sangue e fezes jorrando de todos os seus orifícios. Se a Vida do alvo for maior que 10, faça uma rolagem de ataque de Intelecto contra a Força do alvo. Em caso de sucesso, o alvo sofre 1d6+2 de dano e fica aturdido por 1 rodada, enquanto suas entranhas expelem o próprio conteúdo de forma violenta e espetacular. Se esse dano o incapacitar, excrementos, órgãos e sangue explodem de seu corpo, matando o alvo instantaneamente. Cada criatura a até 2 metros de um ponto no espaço ocupado pelo alvo deve fazer uma rolagem de desafio de Vontade; se fracassar, fica debilitada por 1 rodada. Rolagem de Ataque 20+ O alvo sofre 1d6 de dano extra."},{"id":"proibida-lingua-rasgada","nome":"Língua Rasgada","tipo":"Ataque","trad":"Proibida","grau":1,"texto":"Alvo: Uma criatura capaz de falar a curta distância Você cospe no alvo. Faça uma rolagem de ataque de Intelecto contra a Vontade do alvo. Em caso de sucesso, sua língua se torna bifurcada e você assume o controle da boca do alvo pelo tempo que conseguir se concentrar, até um máximo de 1 hora. Enquanto o efeito durar, sempre que falar poderá usar sua boca ou a boca do alvo, desde que ele esteja a, no máximo, 1,5 quilômetro de você. Quando você fala pela boca do alvo, usa a própria voz dele. Rolagem de Ataque 20+ O efeito não exige concentração."},{"id":"proibida-obediencia","nome":"Obediência","tipo":"Ataque","trad":"Proibida","grau":1,"texto":"Alvo: Uma criatura viva a curta distância Você fisga a alma do alvo. Faça uma rolagem de ataque de Intelecto contra a Vontade do alvo. Em caso de sucesso, durante o próximo minuto, o alvo deve escolher ao final de cada rodada se deseja sofrer 1d6 de dano ou sofrer a aflição compelido por 1 rodada."},{"id":"proibida-fim-da-visao","nome":"Fim da Visão","tipo":"Ataque","trad":"Proibida","grau":2,"texto":"Alvo: Uma criatura dotada de visão, a curta distância Os olhos do alvo incham e se distendem em suas órbitas. Se o alvo possui 15 ou menos de Vida, ele sofre 2d6 de dano, seus olhos explodem e ele fica cego. Se o alvo possui 15 ou mais de Vida, faça uma rolagem de ataque de Intelecto contra a Força do alvo; se possui 30 ou mais de vida, o ataque sofre 1 revés. Em caso de sucesso, o alvo fica cego enquanto você estiver concentrado, por até 1 minuto. Ao final de cada rodada enquanto o efeito durar, o alvo deve fazer uma rolagem de desafio de Força; se fracassar, sofre 1d6 de dano. Se ele sofrer três fracassos antes do efeito terminar, ele fica cego permanentemente — seu olhos rebentam e o humor vítreo escorre pelo seu rosto. Rolagem de Ataque 20+ O efeito não exige concentração."},{"id":"proibida-larvas-vorazes","nome":"Larvas Vorazes","tipo":"Ataque","trad":"Proibida","grau":2,"texto":"Alvo: Uma criatura viva a média distância Duração: 1 minuto A barriga do alvo se enche de larvas famintas, que causam 2d6 de dano. Ao final de cada rodada pela duração do feitiço, o alvo deve fazer uma rolagem de desafio de Força; se fracassar, sofre 1d6 de dano e fica debilitado por 1 rodada. Com um sucesso, não há efeito; no terceiro sucesso, o alvo vomita um enxame de larvas agitadas, e o efeito termina. Um alvo que ficar incapacitado pelo dano do feitiço morre instantaneamente, e uma nuvem de moscas negras se espalha por uma esfera de 5 metros de raio a partir de um ponto dentro desse espaço. As moscas obscurecem fortemente a área, e permanecem por 1 minuto ou até serem dispersadas por fogo ou vento."},{"id":"proibida-fim-do-desejo","nome":"Fim do Desejo","tipo":"Ataque","trad":"Proibida","grau":3,"texto":"Alvo: Uma criatura viva a curta distância O alvo sente uma dor interna aguda. Faça uma rolagem de ataque de Intelecto contra a Força do alvo. Em caso de sucesso, o alvo sofre 3d6 de dano e fica aturdido por 1d6 rodadas, enquanto os despojos lamentáveis de seus órgãos reprodutivos caem de seu corpo. Rolagem de Ataque 20+ O alvo sofre 3d6 de dano extra e também fica prostrado; ele não pode se levantar enquanto estiver aturdido dessa maneira."},{"id":"proibida-separar-osso-da-carne","nome":"Separar Osso da Carne","tipo":"Ataque","trad":"Proibida","grau":3,"texto":"Alvo: Uma criatura com estrutura óssea a média distância Os ossos do alvo se deslocam sob a pele. Faça uma rolagem de ataque de Intelecto contra a Força do alvo. Em caso de sucesso, o alvo sofre 6d6 de dano. Se esse dano incapacitar o alvo, ele morre instantaneamente; seus ossos se desprendem da carne, criando um cadáver animado do mesmo tamanho do alvo, que ocupa seu espaço anterior. A cada rodada, o cadáver animado ataca a criatura mais próxima; se houver mais de um alvo em potencial, escolha o alvo aleatoriamente. Rolagem de Ataque 20+ O alvo sofre 2d6 de dano extra."},{"id":"proibida-permuta-de-almas","nome":"Permuta de Almas","tipo":"Ataque","trad":"Proibida","grau":4,"texto":"Alvo: Duas criaturas mortais a média distância Você agarra a alma dos alvos. Faça uma rolagem de ataque de Intelecto contra a Vontade de cada alvo. Em caso de sucesso, o alvo fica aturdido por 1 minuto. Rolagem de Ataque 20+ O alvo também fica atordoado enquanto estiver aturdido dessa forma. Especial Se obtiver sucesso contra ambos os alvos, suas almas trocarão de corpos permanentemente. Cada alvo também ganha 1d6 pontos de Insanidade. Cada alma utiliza os atributos, características e habilidades do novo corpo, com as seguintes exceções: • Todos os idiomas e profissões • Valores de Intelecto e Vontade (recalcule a Percepção, se necessário) • Valores de Insanidade e de Corrupção • Todos os seus talentos • Todas as tradições que já descobriu e todos os feitiços que conhece."},{"id":"proibida-juncao-repugnante","nome":"Junção Repugnante","tipo":"Ataque","trad":"Proibida","grau":5,"texto":"Alvo: Duas criaturas em seu campo de visão, a curta distância entre si e a média distância de você As formas dos alvos tornam-se dispersas por um instante. Faça uma rolagem de ataque de Intelecto contra a Força de cada alvo. Com um sucesso, o alvo sofre 3d6 de dano e fica debilitado por 1 rodada. Rolagem de Ataque 20+ O alvo sofre 3d6 de dano extra. Especial Se obtiver sucesso contra ambos os alvos, seus corpos se fundem permanentemente, formando uma única criatura, que fica debilitada até completar um descanso. A aparência da nova criatura fica a seu critério. A criatura resultante da junção combina os atributos, características e demais habilidades dos alvos da maneira descrita a seguir: • Ela possui o valor mais alto em Força e o menor valor em Agilidade entre os alvos. Cada alvo mantém seu próprio Intelecto e Vontade. • O alvo adquire 2d6 pontos de Insanidade, que substitui os valores de Insanidade dos alvos, caso existam. Some os valores de Corrupção dos alvos, caso existam."},{"id":"protecao-proteger-local","nome":"Proteger Local","tipo":"Utilitário","trad":"Proteção","grau":0,"texto":"Área: Uma esfera com raio de 10 metros centralizada em um ponto ao seu alcance Duração: 6 horas Um campo invisível surge ao longo da circunferência da área. Enquanto o efeito durar, você saberá sempre que uma criatura de tamanho 1/2 ou maior vinda de fora entrar na área. Se você estiver dormindo, despertará quando isso acontecer."},{"id":"protecao-tranca-magica","nome":"Tranca Mágica","tipo":"Utilitário","trad":"Proteção","grau":0,"texto":"Alvo: Um objeto a curta distância que pode ser aberto ou fechado, como uma porta, um baú ou uma janela Duração: 1 minuto O feitiço fecha e tranca o alvo. Enquanto o efeito durar, nenhuma criatura além de você pode abri-lo por meios não mágicos, embora ele possa ser destruído."},{"id":"protecao-campo-de-forca","nome":"Campo de Força","tipo":"Utilitário","trad":"Proteção","grau":1,"texto":"Duração: 1 minuto; veja o efeito Um campo de força invisível o envolve e se move com você. O campo tem Vida 10. Enquanto o efeito durar, o campo de força sofre todo o dano dos ataques direcionados a você. Se o dano total causado ao campo de força for igual à Vida dele, o efeito termina imediatamente."},{"id":"protecao-evadir","nome":"Evadir","tipo":"Utilitário","trad":"Proteção","grau":1,"texto":"Você se move até quatro vezes a sua Velocidade sem desencadear ataques livres. Desencadeada Você pode usar uma ação desencadeada para conjurar este feitiço quando sofrer dano. Neste caso, você se move até o dobro sua Velocidade sem desencadear ataques livres."},{"id":"protecao-santuario","nome":"Santuário","tipo":"Utilitário","trad":"Proteção","grau":1,"texto":"Alvo: Uma criatura ao seu alcance Duração: 1 minuto; veja o efeito Você toca o alvo, fica escondido de todas as criaturas pela duração do feitiço. O efeito se encerra imediatamente quando o alvo faz um ataque."},{"id":"protecao-vigilancia","nome":"Vigilância","tipo":"Utilitário","trad":"Proteção","grau":2,"texto":"Alvo: Uma criatura ao seu alcance Duração: 4 hora Ao tocar o alvo, você intensifica sua prontidão e percepção. Enquanto o efeito durar, o alvo faz rolagens de desafio de Percepção com 1 dádiva e não pode ser encantado, compelido, amedrontado, surpreendido ou posto para dormir por magia."},{"id":"protecao-vigor","nome":"Vigor","tipo":"Utilitário","trad":"Proteção","grau":2,"texto":"Alvo: Uma criatura ao seu alcance Duração: 1 hora Você toca o alvo, concedendo-lhe um bônus de +10 em Vida pela duração do feitiço."},{"id":"protecao-campo-de-protecao","nome":"Campo de Proteção","tipo":"Utilitário","trad":"Proteção","grau":3,"texto":"Área: Uma esfera com raio de 3 metros centralizada em um ponto ao seu alcance Duração: 1 minuto Uma barreira imóvel e invisível surge ao longo da circunferência da área, permanecendo pela duração do feitiço. Ao conjurar o feitiço, você designa qualquer quantidade de criaturas a média distância de você. As criaturas designadas podem se mover livremente e fazer ataques através da barreira. Nenhuma outra criatura pode atravessar a barreira ou fazer ataques com armas corpo a corpo contra alvos do outro lado."},{"id":"protecao-protecao-contra-feiticos","nome":"Proteção Contra Feitiços","tipo":"Utilitário","trad":"Proteção","grau":3,"texto":"Alvo: Uma criatura ao seu alcance Duração: 1 hora Você toca o alvo, e enquanto o efeito durar, lhe concede proteção contra feitiços. Criaturas que atacam o alvo com feitiços fazem as rolagens de ataque com 1 revés. Por sua vez, o alvo faz rolagens de desafio com 1 dádiva para resistir aos efeitos de feitiços."},{"id":"protecao-invulnerabilidade","nome":"Invulnerabilidade","tipo":"Utilitário","trad":"Proteção","grau":4,"texto":"Alvo: Uma criatura ao seu alcance Duração: Concentração, até 1 minuto Você toca o alvo, que se torna imune a qualquer dano pela duração do feitiço."},{"id":"protecao-globo-de-negacao","nome":"Globo de Negação","tipo":"Utilitário","trad":"Proteção","grau":5,"texto":"Área: Uma esfera com raio de 5 metros centralizada em um ponto ao seu alcance Duração: 1 minuto Uma barreira imóvel e invisível surge ao longo da circunferência da área, permanecendo pela duração do feitiço. Rolagens de ataque com feitiços de grau 5 ou inferior contra alvos atrás da barreira resultam automaticamente em fracassos. Além disso, nenhum feitiço de grau 5 ou inferior pode afetar a área dentro da barreira. Feitiços conjurados de dentro da barreira não podem ter pontos de origem fora dela."},{"id":"runas-decifrar-escrita","nome":"Decifrar Escrita","tipo":"Utilitário","trad":"Runas","grau":0,"texto":"Duração: 1 minuto Enquanto o efeito durar, você pode ler qualquer inscrição ou texto que enxergar."},{"id":"runas-runa-da-busca","nome":"Runa da Busca","tipo":"Utilitário","trad":"Runas","grau":0,"texto":"Alvo: Uma criatura ou objeto ao seu alcance Duração: 1 hora Você toca o alvo e o marca com um selo que permanece pela duração do feitiço. Você sempre sabe a localização exata da criatura ou objeto que carrega o selo."},{"id":"runas-glifo-do-fogo","nome":"Glifo do Fogo","tipo":"Ataque","trad":"Runas","grau":1,"texto":"Alvo: Um ponto no espaço a curta distância Duração: 1 minuto Um glifo flamejante aparece no alvo pela duração do feitiço. Ao conjurar o feitiço e ao final de cada rodada enquanto ele durar, o glifo libera chamas que se espalham por uma esfera com 2 metros de raio, centralizada em um ponto no espaço do alvo, causando 1d6+2 de dano a tudo na área. Cada criatura na área deve fazer uma rolagem de desafio de Agilidade com 1 revés; em caso de sucesso, não sofre dano."},{"id":"runas-marca-da-ruina","nome":"Marca da Ruína","tipo":"Ataque","trad":"Runas","grau":1,"texto":"Alvo: Uma criatura viva a curta distância Faça uma rolagem de ataque de Intelecto contra a Agilidade do alvo. Com um sucesso, você vincula uma runa ao alvo por 1 minuto. Uma vez por rodada, enquanto durar o feitiço, sempre que o alvo sofrer dano a Marca causa 1d6 de dano extra."},{"id":"runas-escudo-runico","nome":"Escudo Rúnico","tipo":"Utilitário","trad":"Runas","grau":1,"texto":"Alvo: Uma criatura que você pode alcançar Duração: 1 minuto Você inscreve uma runa que permanece no alvo pela duração do feitiço. Criaturas que fazem ataques com armas contra o portador da runa sofrem 1 revés nas rolagens de ataque."},{"id":"runas-carcere-runico","nome":"Cárcere Rúnico","tipo":"Ataque","trad":"Runas","grau":2,"texto":"Alvo: Uma criatura viva em seu campo de visão a média distância Duração: 1 minuto Um anel de glifos flamejantes envolve o alvo e permanece no lugar pela duração do feitiço. Se o alvo deixar esse espaço e atravessar as runas, deve fazer uma rolagem de desafio de Força com 1 revés. Se fracassar, sofre 6d6 de dano; em caso de sucesso, sofre metade do dano."},{"id":"runas-runa-da-ocultacao","nome":"Runa da Ocultação","tipo":"Utilitário","trad":"Runas","grau":2,"texto":"Alvo: Uma criatura ao seu alcance Duração: 1 hora Você toca no alvo, que fica marcado com uma runa. Enquanto o efeito durar, o alvo não pode ser encontrado por magia, e se estiver em uma área obscurecida ao final da rodada, ele fica escondido automaticamente até que use uma ação ou se mova."},{"id":"runas-armadilha-de-selo","nome":"Armadilha de Selo","tipo":"Utilitário","trad":"Runas","grau":3,"texto":"Área: Um círculo com raio de 4 metros centralizado em um ponto a média distância Duração: 1 minuto Uma runa surge no ponto de origem e permanece ali pela duração do feitiço. Quando uma criatura entra na área vinda de fora, e ao final de cada rodada enquanto o feitiço durar, relâmpagos crepitantes irrompem da runa, causando 2d6 de dano a tudo que estiver na área. Cada criatura na área deve fazer uma rolagem de desafio de Agilidade. Se fracassar, fica imobilizada por 1 rodada; em caso de sucesso, sofre apenas metade do dano."},{"id":"runas-runa-da-potencia","nome":"Runa da Potência","tipo":"Utilitário","trad":"Runas","grau":3,"texto":"Alvo: Uma criatura ao seu alcance Duração: 1 minuto Uma runa cintilante aparece no local onde você toca o alvo. Enquanto o efeito durar, o alvo faz rolagens de ataque e de desafio de Força com 2 dádivas, e seus ataques com armas corpo a corpo causam 2d6 de dano extra."},{"id":"runas-arma-runica","nome":"Arma Rúnica","tipo":"Utilitário","trad":"Runas","grau":4,"texto":"Alvo: Uma arma ao seu alcance Duração: 1 minuto Você inscreve uma runa cintilante na arma alvo. Enquanto o efeito durar, ataques feitos com essa arma causam 3d6 de dano extra."},{"id":"runas-runa-do-poder","nome":"Runa do Poder","tipo":"Utilitário","trad":"Runas","grau":5,"texto":"Alvo: Uma criatura ao seu alcance Duração: 1 hora Uma runa cintilante aparece no local onde você toca o alvo. Enquanto o efeito durar, o alvo faz rolagens de ataque e desafio com 2 dádivas, recebe um bônus de +20 em Vida e causa 1d6 de dano extra em qualquer ataque que cause dano."},{"id":"sombras-lamina-do-anoitecer","nome":"Lâmina do Anoitecer","tipo":"Utilitário","trad":"Sombras","grau":0,"texto":"Duração: 1 minuto; veja o efeito Fios de escuridão formam uma lâmina sólida, que permanece em sua mão enquanto o feitiço durar ou até você a largar. A lâmina funciona como uma arma rápida para a mão secundária com a propriedade acuidade e causa 1d6 de dano. A lâmina causa 1d6 de dano extra quando você obtém sucesso em uma rolagem de ataque contra um alvo em uma área obscurecida por sombras ou escuridão. Ao conjurar este feitiço, você pode realizar um ataque com a lâmina."},{"id":"sombras-muralha-de-escuridao","nome":"Muralha de Escuridão","tipo":"Utilitário","trad":"Sombras","grau":0,"texto":"Área: Um círculo com raio de 2 metros, em qualquer orientação, centralizado em um ponto a média distância Duração: 1 minuto A área se torna opaca pela duração do feitiço e obscurece completamente o que está dentro ou atrás dela, bloqueando toda a luz proveniente de fontes naturais."},{"id":"sombras-escuridao","nome":"Escuridão","tipo":"Utilitário","trad":"Sombras","grau":1,"texto":"Área: Uma esfera com raio de 5 metros centralizada em um ponto a curta distância Duração: 1 minuto Uma escuridão densa e profunda preenche a área, obscurecendo-a completamente pela duração do feitiço. A escuridão anula toda a luz proveniente de fontes naturais e aquela criada por feitiços de grau 0, além de bloquear toda a forma de visão não mágica, exceto a visão verdadeira. Se você conjurar esse feitiço em um objeto esteja tocando, a área de escuridão passa a se mover com ele. Se o objeto for completamente coberto, o efeito do feitiço fica suprimido enquanto ele continuar coberto."},{"id":"sombras-visao-no-escuro","nome":"Visão No Escuro","tipo":"Utilitário","trad":"Sombras","grau":1,"texto":"Alvo: Uma criatura ao seu alcance Duração: 1 hora Você toca o alvo, que recebe visão no escuro pela duração do feitiço."},{"id":"sombras-dardo-sombrio","nome":"Dardo Sombrio","tipo":"Ataque","trad":"Sombras","grau":1,"texto":"Alvo: Uma criatura ou objeto a média distância Um projétil de escuridão densa e profunda salta da sua mão. Faça uma rolagem de ataque de Intelecto contra a Agilidade do alvo. Em caso de sucesso, o alvo do ataque sofre 2d6 de dano e faz rolagens de desafio de Percepção com 3 reveses por 1 minuto."},{"id":"sombras-monstro-sombrio","nome":"Monstro Sombrio","tipo":"Utilitário","trad":"Sombras","grau":2,"texto":"Área: Um cubo com 1 metro de lado, com origem em um ponto a média distância Duração: 1 minuto Fios de escuridão se reúnem na área para formar um monstro médio compelido e com o traço voador. O monstro sombrio pode ter qualquer aparência que você desejar. Se ele ficar incapacitado, o efeito termina."},{"id":"sombras-passo-sombrio","nome":"Passo Sombrio","tipo":"Utilitário","trad":"Sombras","grau":2,"texto":"Duração: 1 minuto Enquanto o efeito durar, sempre que você entrar em um espaço obscurecido por sombras ou escuridão, poderá emergir instantaneamente em um espaço desocupado também obscurecido por sombras ou escuridão desde que esteja a média distância do ponto onde você entrou. Você pode se mover dessa maneira uma vez por rodada."},{"id":"sombras-raios-negros-do-submundo","nome":"Raios Negros do Submundo","tipo":"Ataque","trad":"Sombras","grau":3,"texto":"Alvo: Até três criaturas a média distância Três projéteis de escuridão pululante saltam de sua mão, dividindo-se entre os alvos conforme sua escolha. Para cada projétil, faça uma rolagem de ataque de Intelecto contra a Agilidade do alvo. Em caso de sucesso, o alvo sofre 2d6 de dano e é deslocado 1d6 metros para longe de você. Rolagem de Ataque 20+ O alvo sofre 1d6 de dano extra."},{"id":"sombras-magia-sombria","nome":"Magia Sombria","tipo":"Utilitário","trad":"Sombras","grau":3,"texto":"Escolha um dos seus feitiços de grau 2 ou inferior de uma tradição diferente da tradição Sombria. Você conjura o feitiço sem gastar uma conjuração, mesmo que não tenha mais conjurações daquele feitiço disponíveis."},{"id":"sombras-portais-sombrios","nome":"Portais Sombrios","tipo":"Utilitário","trad":"Sombras","grau":4,"texto":"Alvo: Seis cubos, cada um com 1 metro de lado, a longa distância Duração: 1 minuto A escuridão preenche cada cubo, obscurecendo totalmente seu espaço e bloqueando toda visão não mágica, exceto visão verdadeira. Atribua um número, de 1 a 6, a cada cubo. Quando uma criatura entra em um dos cubos, ela deve fazer uma rolagem de desafio de Intelecto para escolher de qual cubo sairá. Em caso de sucesso, a criatura sai instantaneamente para um espaço desocupado a partir do cubo escolhido. Se fracassar, a criatura rola 1d6 para determinar de qual cubo ela sairá. De uma forma ou de outra, a criatura decide em que direção sai do cubo."},{"id":"sombras-enervacao","nome":"Enervação","tipo":"Ataque","trad":"Sombras","grau":5,"texto":"Alvo: Uma criatura viva a longa distância Um feixe negro salta da palma da sua mão. Faça uma rolagem de ataque de Intelecto contra a Agilidade do alvo. Em caso de sucesso, o alvo sofre uma penalidade de –20 em Vida por 1 hora. Enquanto sofrer essa penalidade, o alvo também fica debilitado. Rolagem de Ataque 20+ A penalidade é de –30."},{"id":"tecnomancia-gambiarra","nome":"Gambiarra","tipo":"Utilitário","trad":"Tecnomancia","grau":0,"texto":"Alvo: Um objeto de tamanho 2 ou menor ao seu alcance que possua 1 ou mais pontos de dano mas que não esteja destruído Você toca o alvo, e remove 1d6 pontos de dano dele."},{"id":"tecnomancia-ferramenta-ajustavel-magica","nome":"Ferramenta Ajustável Mágica","tipo":"Ataque","trad":"Tecnomancia","grau":0,"texto":"Alvo: Uma criatura ou objeto a curta distância Você cria e arremessa uma ferramenta ajustável. Faça uma rolagem de ataque de Intelecto contra a Defesa do alvo. Em caso de sucesso, o alvo sofre 1d6+1 de dano e fica prostrado. Rolagem de Ataque 20+ O alvo também fica debilitado até o final da rodada."},{"id":"tecnomancia-lancador-de-virotes","nome":"Lançador de Virotes","tipo":"Ataque","trad":"Tecnomancia","grau":1,"texto":"Área: Um cubo com 1 metros de lado, com origem em um ponto ao seu alcance e apoiado sobre uma superfície sólida Duração: 1 minuto Você cria, na área. uma torreta de besta de Tamanho 1. A torreta tem Defesa 5 e Vida igual ao valor do seu Intelecto. Ela permanece pela duração do feitiço ou até ser destruída. Ao final de cada rodada, a torreta dispara contra uma criatura ou objeto que está a longa distância. Faça uma rolagem de ataque de Intelecto contra a Defesa do alvo. Com um sucesso, o alvo sofre 2d6 de dano. Rolagem de Ataque 20+ O alvo sofre 1d6 de dano extra."},{"id":"tecnomancia-escudo-faiscante","nome":"Escudo Faiscante","tipo":"Utilitário","trad":"Tecnomancia","grau":1,"texto":"Duração: 1 minuto Você cria um escudo mágico em seu braço, que permanece pela duração do feitiço. Uma vez por rodada, quando uma criatura o ataca com uma arma de combate corpo a corpo e obtém sucesso, o escudo dispara faíscas; o atacante deve fazer uma rolagem de desafio de Agilidade. Se fracassar, a criatura sofre 1d6 de dano, é lançada a 1d3 metros de distância de você, e fica prostrada ao final deste movimento."},{"id":"tecnomancia-estrepes","nome":"Estrepes","tipo":"Utilitário","trad":"Tecnomancia","grau":1,"texto":"Área: Um círculo no chão com raio de 5 metros centralizado em um ponto a média distância Duração: 1 minuto Fragmentos metálicos irregulares irrompem do ponto de origem, cobrindo todas as superfícies horizontais na área pela duração do feitiço. Uma criatura que entre ou atravesse a área precisa de um sucesso em uma rolagem de desafio de Agilidade ou sofre 1d6+1 de dano e fica lenta. Se a criatura já estiver lenta dessa maneira, fica prostrada e imobilizada. As aflições lenta e imobilizada são removidas quando ela curar dano."},{"id":"tecnomancia-lanca-chamas","nome":"Lança-Chamas","tipo":"Utilitário","trad":"Tecnomancia","grau":2,"texto":"Duração: Veja o efeito Você cria um lança-chamas, uma arma que possui seis cargas. Ele aparece nas suas mãos — ou aos seus pés, se suas mãos não estiverem livres. Quando sua última carga é utilizada, o lançachamas se desmonta em peças sobressalentes. Uma criatura que estiver empunhando o lança-chamas pode usar uma ação para gastar uma carga, liberando chamas ao longo de uma linha de 5 metros de comprimento e 1 metro de largura a partir de um ponto que em seu alcance. As chamas causam 2d6 de dano a tudo que está na área; cada criatura que conseguir um sucesso em uma rolagem de desafio de Agilidade sofre metade do dano. O lança-chamas explode quando a criatura que o empunha sofre dano de fogo ou relâmpago. Com a explosão, chamas preenchem uma esfera com raio de 5 metros, com origem em um ponto no espaço da criatura, causando 1d6 de dano por cada carga que não foi utilizada a tudo que está na área. Uma criatura dentro da área que conseguir um sucesso em uma rolagem de desafio de Agilidade sofre metade do dano."},{"id":"tecnomancia-granadas","nome":"Granadas","tipo":"Ataque","trad":"Tecnomancia","grau":2,"texto":"Alvo: Até três criaturas vivas a curta distância Você lança três granadas, que podem ser arremessadas nos os alvos que você escolher. Quando uma granada atinge um alvo, ou se colidir com uma criatura ou objeto sólido antes do alvo, ela explode. A explosão causa 1d6+1 de dano de fogo a tudo que estiver em uma esfera com 1 metro de raio, centralizada no alvo ou em um ponto dentro do espaço da criatura ou do objeto. Uma criatura dentro da área que conseguir um sucesso em uma rolagem de desafio de Agilidade sofre metade do dano."},{"id":"tecnomancia-laminas-voadoras","nome":"Lâminas Voadoras","tipo":"Ataque","trad":"Tecnomancia","grau":3,"texto":"Alvo: Até três criaturas ou objetos a média distância Três lâminas voam de sua mão, atingindo os alvos conforme sua escolha. Para cada lâmina, faça uma rolagem de ataque de Intelecto contra a Defesa do alvo. Com um sucesso, o alvo sofre 2d6 de dano. Rolagem de Ataque 20+ O alvo sofre 1d6 de dano extra."},{"id":"tecnomancia-reparar","nome":"Reparar","tipo":"Utilitário","trad":"Tecnomancia","grau":3,"texto":"Alvo: Um objeto de tamanho 3 ou menor que possua 1 ou mais pontos de dano, mas que não esteja destruído, ao seu alcance Você toca no alvo e remove todo o dano dele."},{"id":"tecnomancia-traje-motorizado","nome":"Traje Motorizado","tipo":"Utilitário","trad":"Tecnomancia","grau":4,"texto":"Área: Um cubo com 3 metros de lado, com origem em um ponto ao seu alcance Duração: Até você completar um descanso; veja o efeito Você se concentra por 1 hora, e durante esse período você cria uma armadura de combate motorizada — um construto enorme — na área. O construto permanece pela duração do feitiço ou até ficar incapacitado. Ele não pode usar ações ou se mover sozinho — você precisa entrar na cabine para controlá-lo. Enquanto estiver dentro, use os valores de Defesa e Vida do construto como se fossem seus; mova-se na Velocidade dele; e use os ataques e ações dele no lugar dos seus."},{"id":"tecnomancia-item-magico","nome":"Item Mágico","tipo":"Utilitário","trad":"Tecnomancia","grau":5,"texto":"Alvo: Um objeto ao seu alcance Duração: 1 hora Você toca no alvo, imbuindo-o com poder mágico. Enquanto o efeito durar, as rolagens de ataque ou de desafio para qualquer tarefa que tentar realizar com o alvo são feitas com 1 dádiva. Se o objeto for uma arma, seus ataques causam 1d6 de dano extra. Se for uma armadura, o usuário recebe um bônus de +1 em Defesa. Permanência Se você gastar ingredientes raros no valor de 1 co ao conjurar este feitiço, o efeito dura até que você complete um descanso. Se você conjurar o feitiço dessa maneira no mesmo alvo todos os dias pelo período de um mês, uma semana e um dia, o efeito se torna permanente."},{"id":"teletransporte-buscar","nome":"Buscar","tipo":"Utilitário","trad":"Teletransporte","grau":0,"texto":"Alvo: Um objeto que você consegue segurar com uma mão a média distância O alvo se teletransporta para a sua mão ou aterrissa aos seus pés, se suas mãos estiverem ocupadas."},{"id":"teletransporte-dispensar","nome":"Dispensar","tipo":"Utilitário","trad":"Teletransporte","grau":0,"texto":"Alvo: Um objeto de tamanho 1 ou menor a curta distância O alvo se teletransporta para um espaço desocupado a média distância."},{"id":"teletransporte-divisao","nome":"Divisão","tipo":"Ataque","trad":"Teletransporte","grau":1,"texto":"Alvo: Uma criatura a curta distância em seu campo de visão Faça uma rolagem de ataque de Intelecto contra a Força do alvo. Em caso de sucesso, o alvo sofre 3d6 de dano. Se o alvo ficar incapacitado por esse dano, seu corpo se despedaça, matando-o instantaneamente. Rolagem de Ataque 20+ O alvo sofre 1d6 de dano extra."},{"id":"teletransporte-buraco-glorioso","nome":"Buraco Glorioso","tipo":"Utilitário","trad":"Teletransporte","grau":1,"texto":"Alvo: Dois cubos, cada um com 1 metro de lado, a média distância Duração: 1 minuto Um portal de 30 centímetros de largura se abre no centro de cada cubo e permanece pela duração do feitiço. As fendas não têm espessura; qualquer coisa colocada em uma delas sai instantaneamente pela outra. Quando o efeito termina, as fendas se fecham, possivelmente cortando o que estiver dentro delas, conforme o MJ determinar."},{"id":"teletransporte-trocar","nome":"Trocar","tipo":"Utilitário","trad":"Teletransporte","grau":1,"texto":"Alvo: Uma criatura a longa distância Você e o alvo se teletransportam para trocar de posição. Um alvo relutante pode fazer uma rolagem de desafio de Vontade resistir, anulando o efeito em caso de sucesso. Desencadeada Em seu turno, você pode usar uma ação desencadeada para conjurar este feitiço. Neste caso, o alvo deve estar a curta distância."},{"id":"teletransporte-remover","nome":"Remover","tipo":"Ataque","trad":"Teletransporte","grau":2,"texto":"Alvo: Uma criatura ao seu alcance Faça uma rolagem de ataque de Intelecto contra a Agilidade do alvo. Em caso de sucesso, você toca no alvo e ele se teletransporta para um espaço desocupado em uma superfície sólida em seu campo de visão a média distância. Rolagem de Ataque 20+ O espaço desocupado está a extrema distância."},{"id":"teletransporte-atalho","nome":"Atalho","tipo":"Utilitário","trad":"Teletransporte","grau":2,"texto":"Você se teletransporta para um espaço desocupado em seu campo de visão a longa distância. Desencadeada Em seu turno, você pode usar uma ação desencadeada para conjurar este feitiço. Neste caso, o espaço desocupado está a média distância."},{"id":"teletransporte-passo-ilimitado","nome":"Passo Ilimitado","tipo":"Utilitário","trad":"Teletransporte","grau":3,"texto":"Duração: 1 minuto Em cada um dos seus turnos pela duração do feitiço, você pode usar uma ação desencadeada para se teletransportar para um espaço desocupado em seu campo de visão a média distância."},{"id":"teletransporte-fundir","nome":"Fundir","tipo":"Ataque","trad":"Teletransporte","grau":3,"texto":"Alvo: Uma criatura ou objeto a média distância Faça uma rolagem de ataque de Intelecto contra a Vontade do alvo. Em caso de sucesso, o alvo se teletransporta para um espaço desocupado em uma superfície sólida a média distância de você, e parte dele se funde com a superfície. Ele sofre 6d6 de dano e fica imobilizado. A única maneira de remover essa aflição é destruir o objeto com o qual o alvo está fundido, ou realizar uma ação para serrar um membro aprisionado — causando dano ao alvo igual ao dobro da taxa de cura dele. Rolagem de Ataque 20+ O alvo sofre 2d6 de dano extra e também fica atordoado por 1 rodada."},{"id":"teletransporte-portais","nome":"Portais","tipo":"Utilitário","trad":"Teletransporte","grau":4,"texto":"Área: Dois cubos, cada um com 2 metros de lado, um com origem em um ponto ao seu alcance e o outro com origem em um ponto a extrema distância Duração: 1 minuto Um portal se abre no centro de cada cubo, e permanece aberto pela duração do feitiço. Cada portal tem 1 metro de largura e 2 metros de altura, mas não possui espessura. Cada portal tem uma frente, uma parte traseira e pode ter qualquer orientação. Tudo que entra pela frente de um portal sai instantaneamente para um espaço desocupado pela parte traseira do outro, e vice-versa."},{"id":"teletransporte-viajar","nome":"Viajar","tipo":"Utilitário","trad":"Teletransporte","grau":5,"texto":"Alvo: Até cinco criaturas voluntárias em seu alcance Você toca em cada alvo e indica um destino. Faça uma rolagem de desafio de Intelecto. O MJ pode impor um ou mais reveses à rolagem, conforme sua familiaridade com o destino. Se o nome do lugar não existir, o feitiço falha e a conjuração é desperdiçada. Em caso de sucesso, os alvos são teletransportados para o destino. Se fracassar, cada alvo se teletransporta separadamente para um local a até 1d20 quilômetros do destino, pelo MJ. Se o total da rolagem for 0 ou menos, cada alvo também sofre 10d6 de dano e ganha 1 ponto de Insanidade devido feitiço ter saído horrivelmente errado. Se o espaço no destino não for grande o suficiente para acomodar o alvo, ele sofre 5d6 de dano, ganha 1 ponto de Insanidade e retorna para o espaço de onde saiu. Uma criatura incapacitada por esse dano morre ao chegar, sendo reduzida a um amontoado de sangue, ossos e tripas. Se o espaço de destino não estiver desocupado — dentro de uma parede, por exemplo — o alvo se funde com o material que o preenche o local e morre instantaneamente."},{"id":"tempestade-nevoa","nome":"Névoa","tipo":"Utilitário","trad":"Tempestade","grau":0,"texto":"Área: Um cilindro com 3 metros de altura e 5 metros de raio, centralizado em um ponto a média distância Duração: 1 hora; ver o efeito Uma névoa densa se espalha pela área, que fica parcialmente obscurecida pela duração do feitiço ou até ser dispersada pelo vento."},{"id":"tempestade-choque","nome":"Choque","tipo":"Ataque","trad":"Tempestade","grau":0,"texto":"Alvo: Uma criatura viva a curta distância Faça uma rolagem de ataque de Vontade contra a Agilidade do alvo. Você faz a rolagem de ataque com 1 dádiva se o alvo estiver usando armadura de metal ou for feito de metal. Em caso de sucesso, o alvo sofre 1d6 de dano. Rolagem de Ataque 20+ O alvo também fica aturdido até o final da rodada."},{"id":"tempestade-nevoa-congelante","nome":"Névoa Congelante","tipo":"Ataque","trad":"Tempestade","grau":1,"texto":"Área: Um cilindro com 3 metros de altura e 5 metros de raio, centralizado em um ponto a média distância Duração: 1 minuto; veja o efeito Uma névoa densa se espalha pela área, que fica parcialmente obscurecida pela duração do feitiço ou até ser dispersada pelo vento. O solo na área fica escorregadio e conta como terreno difícil até terminar o efeito. Qualquer criatura que estiver na área quando você conjura o feitiço ou ao final de uma rodada durante a duração do feitiço, deve fazer uma rolagem de desafio de Força. Se fracassar, sofre 1d3 de dano e fica lento por 1 rodada."},{"id":"tempestade-relampago-bifurcado","nome":"Relâmpago Bifurcado","tipo":"Ataque","trad":"Tempestade","grau":1,"texto":"Alvo: Até duas criaturas ou objetos a curta distância um do outro e a média distância de você Para cada alvo, faça uma rolagem de ataque de Vontade contra a Agilidade de cada um. Você faz a rolagem de ataque com 1 dádiva se o alvo estiver usando armadura de metal ou for feito de metal. Com um sucesso, o alvo sofre 1d6+2 de dano. Rolagem de Ataque 20+ O alvo sofre 1d6 de dano extra."},{"id":"tempestade-as-chamas-de-santa-astrid","nome":"As Chamas de Santa Astrid","tipo":"Utilitário","trad":"Tempestade","grau":1,"texto":"Alvo: Até três criaturas ou objetos a curta distância Duração: 1 minuto Chamas verdes inofensivas envolvem cada alvo pela duração do feitiço. Cada alvo emite luz em 1 metro de raio e não pode se tornar invisível ou ocultar-se de criaturas que possam vê-lo; outras criaturas fazem rolagens de ataque contra o alvo com 1 dádiva."},{"id":"tempestade-convocar-relampago","nome":"Convocar Relâmpago","tipo":"Ataque","trad":"Tempestade","grau":2,"texto":"Requisitos: Você deve estar ao ar livre. Alvo: Um ponto no chão a longa distância Um relâmpago cai do céu e atinge o alvo vindo do céu, causando 3d6+5 de dano a tudo que estiver a 3 metros desse ponto. Cada criatura que sofrer dano dessa maneira deve fazer uma rolagem de desafio de Força. Se fracassar, fica surda por 1 hora; em caso de sucesso, sofre apenas metade do dano. Sacrifício Você pode gastar uma conjuração deste feitiço para usar relâmpago bifurcado ."},{"id":"tempestade-nevoa-venenosa","nome":"Névoa Venenosa","tipo":"Ataque","trad":"Tempestade","grau":2,"texto":"Área: Um cilindro com 2 metros de altura e 5 metros de raio, centralizado em um ponto a média distância Duração: 1 minuto; veja o efeito Uma névoa roxa se espalha pela área, que fica fortemente obscurecida pela duração do feitiço ou até ser dispersada pelo vento. A neblina é mais densa que o ar, por isso se acumula em fendas e aberturas no solo abaixo dela. Ao final de cada rodada, pela duração do feitiço, role um d6. Se o número for par, a nuvem se move metade desse valor em metros para longe de você. Quando a névoa surgir, e ao final de cada rodada pela duração do feitiço, cada criatura na área deve obter sucesso em uma rolagem de desafio de Força ou sofrer 1d6 de dano e ficar envenenada por 1 rodada. Enquanto estiver envenenada dessa maneira, a criatura também fica imobilizada."},{"id":"tempestade-relampago","nome":"Relâmpago","tipo":"Ataque","trad":"Tempestade","grau":3,"texto":"Área: Uma linha de 30 metros de comprimento e 1 metro de largura, com origem em um ponto que ao seu alcance O relâmpago percorre 5d6 metros ao longo da área. Se encontrar um objeto sólido antes de chegar ao final da linha, o raio ricocheteia e retorna em linha reta na direção do conjurador, percorrendo a distância restante. O relâmpago causa 5d6 de dano a tudo que estiver na área. Cada criatura na área deve fazer uma rolagem de desafio de Agilidade, com 1 revés se for feita de metal ou estiver usando armadura pesada. Uma criatura que estiver no caminho de um relâmpago que ricocheteia faz a rolagem duas vezes. Em caso de sucesso, a criatura sofre metade do dano."},{"id":"tempestade-tempestade-de-granizo","nome":"Tempestade de Granizo","tipo":"Ataque","trad":"Tempestade","grau":3,"texto":"Área: Um cilindro com 2 metros de altura e 5 metros de raio, centralizado em um ponto a longa distância Duração: 1 minuto Granizo cai das nuvens que se espalham pela área e permanecem pela duração do feitiço, obscurecendo parcialmente a área abaixo delas. Enquanto o efeito durar, todas criaturas na área e em 5 metros de raio da borda dessa área ficam surdas. O terreno na área torna-se difícil até que o granizo derreta. Ao conjurar o feitiço, e ao final de cada rodada por sua duração, a chuva de granizo causa 3d6 de dano a qualquer coisa na área que não esteja sob abrigo. Cada criatura ferida dessa maneira deve fazer uma rolagem de desafio de Agilidade. Se fracassar, ela fica prostrada; em caso de sucesso, sofre apenas metade do dano."},{"id":"tempestade-chuva-acida","nome":"Chuva Ácida","tipo":"Ataque","trad":"Tempestade","grau":4,"texto":"Área: Um cilindro com 2 metros de altura e 5 metros de raio, centralizado em um ponto a longa distância Duração: 1 minuto Chuva ácida de cor verde cai das nuvens que se espalham pela área e permanecem pela duração do feitiço, obscurecendo parcialmente a área abaixo delas. Ao conjurar o feitiço, e ao final de cada rodada por sua duração, a chuva causa 5d6 de dano a qualquer criatura na área que não esteja sob abrigo. Cada criatura que sofrer dano dessa maneira deve fazer uma rolagem de desafio de Força; em caso de sucesso, sofre apenas metade do dano."},{"id":"tempestade-relampago-em-cadeia","nome":"Relâmpago em Cadeia","tipo":"Ataque","trad":"Tempestade","grau":5,"texto":"Alvo: Uma criatura a longa distância; veja o efeito Você arremessa um relâmpago contra o alvo. Faça uma rolagem de ataque de Vontade contra a Agilidade do alvo. Você faz a rolagem de ataque com 1 dádiva se o alvo estiver usando armadura de metal ou for feito de metal. Em caso de sucesso, o alvo sofre 8d6 de dano e você pode repetir o ataque contra outro alvo que esteja a longa distância do primeiro. Cada vez que fizer isso, deve escolher um alvo que não tenha sido atacado por esta conjuração e reduzir o dano causado em 2d6. Quando o número de dados de dano chega a 0, o efeito se encerra."},{"id":"tempo-retardar","nome":"Retardar","tipo":"Ataque","trad":"Tempo","grau":0,"texto":"Alvo: Uma criatura a curta distância em seu campo de visão Faça uma rolagem de ataque de Intelecto contra a Vontade do alvo. Com um sucesso, o alvo fica lento por 1 minuto. Rolagem de Ataque 20+ O alvo também fica debilitado quando fica lento dessa maneira."},{"id":"tempo-rapidez","nome":"Rapidez","tipo":"Utilitário","trad":"Tempo","grau":0,"texto":"Alvo: Uma criatura ao seu alcance que não esteja fatigada Duração: 1 minuto Você toca no alvo, que ganha um bônus de +10 em Velocidade pela duração do feitiço. Quando o efeito termina, o alvo fica fatigado por 1 minuto."},{"id":"tempo-paradoxo-menor","nome":"Paradoxo Menor","tipo":"Ataque","trad":"Tempo","grau":1,"texto":"Alvo: Uma criatura a curta distância em seu campo de visão Faça uma rolagem de ataque de Intelecto contra a Intelecto da criatura. Com um sucesso, o alvo deixa de existir por 1 rodada. Ele reaparece em seu espaço anterior ou no espaço desocupado mais próximo dele, caso este já esteja ocupado. Rolagem de Ataque 20+ Você recupera a conjuração deste feitiço."},{"id":"tempo-reescrever-o-momento","nome":"Reescrever o Momento","tipo":"Utilitário","trad":"Tempo","grau":1,"texto":"Duração: 1 minuto Uma vez por rodada pela duração do feitiço, ao rolar um dado, você pode descartar o resultado e rolá-lo novamente. Você deve usar o segundo resultado."},{"id":"tempo-devagar","nome":"Devagar","tipo":"Ataque","trad":"Tempo","grau":1,"texto":"Alvo: Até cinco criaturas ou objetos a média distância Cada alvo deve fazer uma rolagem de desafio de Vontade. Se fracassar, o alvo fica lento por 1 minuto."},{"id":"tempo-precognicao","nome":"Precognição","tipo":"Utilitário","trad":"Tempo","grau":2,"texto":"Duração: 1 minuto Enquanto o efeito durar, rolagens de ataque contra você são feitas com 1 revés. Além disso, você faz rolagens de desafio para resistir a ataques com 1 dádiva."},{"id":"tempo-salto-temporal","nome":"Salto Temporal","tipo":"Utilitário","trad":"Tempo","grau":2,"texto":"Duração: 1 minuto Você salta para frente no tempo, desaparecendo do seu espaço atual. Em qualquer momento enquanto o efeito durar, você pode reaparecer no espaço de onde saiu — ou no espaço aberto mais próximo dele, caso este esteja ocupado. Do contrário, você reaparece ao final da rodada quando o efeito termina."},{"id":"tempo-acelerar","nome":"Acelerar","tipo":"Utilitário","trad":"Tempo","grau":3,"texto":"Alvo: Uma criatura ao seu alcance Duração: 1 minuto Você toca o alvo. Enquanto o efeito durar, ele pode fazer um turno rápido e um turno lento na mesma rodada. Quando o efeito termina, o alvo fica fatigado por 1d6 minutos."},{"id":"tempo-desacelerar","nome":"Desacelerar","tipo":"Ataque","trad":"Tempo","grau":3,"texto":"Área: Uma esfera com raio de 3 metros centralizada em um ponto a média distância Cada criatura escolhida por você na área deve obter sucesso em uma rolagem de desafio de Vontade ou fica lenta por 1 minuto. Enquanto estiver lenta dessa maneira, quando a criatura fizer um turno lento, ela poderá usar uma ação ou se mover, mas não ambos."},{"id":"tempo-duplicata-temporal","nome":"Duplicata Temporal","tipo":"Utilitário","trad":"Tempo","grau":4,"texto":"Área: Um cubo grande o suficiente para acomodar uma criatura do seu Tamanho, com origem em um ponto em um número de metros igual à sua Velocidade Duração: 1 minuto; veja o efeito Você faz com que uma versão futura de si mesmo apareça na área e permaneça em seu tempo pela duração do feitiço. Até o fim do efeito, você e sua duplicata futura podem cada um fazer um turno a cada rodada. Contudo, o paradoxo de sua existência duplicada impõe 1 revés a todas as rolagens de ataque e de desafio feitas por ambos. Você e sua versão futura possuem atributos e características idênticos. Embora possam agir separadamente, vocês contam como uma única criatura para fins de compartilhamento de recursos. Portanto, se um de vocês sofrer dano ou adquirir Insanidade, isso se aplica a ambos. Se um de vocês gastar a conjuração de um feitiço, essa conjuração é considerada gasta para os dois. Da mesma forma, se um de vocês sofrer uma aflição ou se beneficiar de um efeito contínuo, a aflição ou o efeito se aplica a ambos. Sua versão futura possui cópias idênticas de tudo o que você veste e carrega, com algumas exceções. Primeiro, se você ou sua duplicata consumir ou gastar um item — como ao usar uma poção de cura — o item é perdido para ambos. Além disso, se você possui uma relíquia, deve escolher se ela é carregada por você ou por sua versão futura. Se você ou sua duplicata futura ficarem incapacitados, o outro também ficará. Se você morrer, sua versão futura desaparece imediatamente. Quando o efeito termina, você e sua versão futura desaparecem. Você reaparece 1 minuto depois, no espaço que sua duplicata futura ocupava ou, caso ele esteja ocupado, no espaço desocupado mais próximo."},{"id":"tempo-viagem-no-tempo","nome":"Viagem No Tempo","tipo":"Utilitário","trad":"Tempo","grau":5,"texto":"Escolha um instante no tempo em até 100 anos no futuro. Você desaparece da existência. Quando o tempo dentro do jogo atingir o tempo que você escolheu, você reaparece imediatamente no espaço de onde saiu ou no espaço desocupado mais próximo dele, caso ele esteja ocupado."},{"id":"terra-ferrao-telurico","nome":"Ferrão Telúrico","tipo":"Ataque","trad":"Terra","grau":0,"texto":"Alvo: Uma criatura sobre o chão a curta distância Uma aguilhão afiado irrompe do chão sob o alvo. Faça uma rolagem de ataque de Vontade contra a Agilidade do alvo. Com um sucesso, o alvo sofre 1d6 de dano e fica prostrado. Rolagem de Ataque 20+ O alvo sofre 1d6 de dano extra."},{"id":"terra-modelar-terra-e-pedra","nome":"Modelar Terra e Pedra","tipo":"Utilitário","trad":"Terra","grau":0,"texto":"Alvo: Um objeto de tamanho 1 ou menor, feito de terra ou pedra, que está ao seu alcance Duração: Permanente Você pode moldar o alvo como se fosse feito de argila macia; uma vez moldado ele retorna à sua dureza normal."},{"id":"terra-armadura-rochosa","nome":"Armadura Rochosa","tipo":"Utilitário","trad":"Terra","grau":1,"texto":"Duração: Concentração, até 1 minuto Fragmentos de rocha espalham-se sobre seu corpo, cobrindo-o completamente. Enquanto o efeito durar, rolagens de ataque contra sua Defesa, Força ou Agilidade são feitas com 1 revés, e você sofre metade do dano causado por armas. Quando o efeito termina, a rocha que o envolve explode em uma esfera com 1 metro de raio centrada em um ponto ao seu alcance. Tudo o que estiver na área da explosão, exceto você, sofre 1d6 de dano por cada rodada que você se concentrou nesse feitiço. Cada criatura que estiver dentro da área deve fazer uma rolagem de desafio de Agilidade; em caso de sucesso, sofre metade do dano."},{"id":"terra-laminas-de-pedra","nome":"Lâminas de Pedra","tipo":"Ataque","trad":"Terra","grau":1,"texto":"Área: Um cone, com 3 metros de comprimento, com origem em um ponto ao seu alcance Você arremessa estilhaços de pedra que causam 2d6 de dano a tudo na área. Cada criatura na área deve fazer uma rolagem de desafio de Agilidade, sofrendo metade do dano em caso de sucesso. Se fracassar, a criatura sofre um ferimento com sangramento persistente e sofre 1d6 de dano ao final de cada rodada, até curar qualquer quantidade de dano ou até que ela, ou outra criatura, use uma ação para estancar o sangramento."},{"id":"terra-tremor","nome":"Tremor","tipo":"Ataque","trad":"Terra","grau":1,"texto":"Área: Uma círculo no chão com raio de 4 metros centralizado em um ponto ao seu alcance Duração: 1 minuto O chão treme e se agita. Qualquer criatura que estiver em pé na área ou que entrar nela, exceto você, deve fazer uma rolagem de desafio de Agilidade. Se fracassar, fica prostrada e não pode se levantar pela duração do feitiço."},{"id":"terra-avalanche","nome":"Avalanche","tipo":"Ataque","trad":"Terra","grau":2,"texto":"Área: Um círculo no chão com raio de 2 metros, centralizado em um ponto ao seu alcance, e um cone de 5 metros de comprimento, com origem em um ponto ao seu alcance Você levanta a camada superior do solo no círculo e a arremessa no formato de cone. Ambas as áreas contam como terreno difícil até que os escombros sejam removidos. Tudo que estiver dentro do cone sofre 4d6 de dano. Cada criatura na área que obtiver sucesso em uma rolagem de desafio de Agilidade sofre metade do dano."},{"id":"terra-moldar-terra-e-pedra","nome":"Moldar Terra e Pedra","tipo":"Utilitário","trad":"Terra","grau":2,"texto":"Área: Um cubo feito de terra ou pedra, com 4 metros de lado, com origem em um ponto ao seu alcance Duração: Permanente; veja o efeito Ao conjurar o feitiço, você deve se concentrar e manter contato com a área por 1 minuto. Ao final desse período, você remodela a terra e a pedra da área como se fossem feitas de argila macia. O material então retorna à sua dureza normal. Você pode lançar este feitiço para criar aberturas em paredes de rocha, selar portas, formar armas de pedra ou remover entulhos para liberar passagens."},{"id":"terra-cair-por-terra","nome":"Cair Por Terra","tipo":"Ataque","trad":"Terra","grau":3,"texto":"Área: Um cubo com 10 metros de lado, com origem em um ponto a longa distância Duração: 1 minuto A gravidade se intensifica repentinamente na área afetada, que conta como um terreno difícil por toda a sua duração. Cada criatura dentro área, ou que entrar nela, deve fazer uma rolagem de desafio de Força com 1 revés; se fracassar, fica prostrada e imobilizada pela duração do feitiço. Enquanto estiver imobilizada dessa forma, a criatura não consegue se levantar. Se estiver voando, ela cai e sofre dano dobrado ao atingir o solo."},{"id":"terra-erupcao","nome":"Erupção","tipo":"Ataque","trad":"Terra","grau":3,"texto":"Área: Um cilindro com 10 metros de altura e 2 metros de raio, centralizado em um ponto a média distância O solo entra em erupção, lançando escombros ao ar que caem ao chão, causando 5d6 de dano a tudo que estiver dentro da área afetada. Criaturas e objetos na área são lançados por 1d6 metros para longe do ponto de origem. Cada criatura dentro da área de efeito deve fazer uma rolagem de desafio de Força. Se fracassar, ela fica prostrada; em caso de sucesso, sofre apenas metade do dano. Após o feitiço terminar, o terreno num raio de 5 metros do ponto de origem fica coberto de destroços, sendo considerado terreno difícil até os escombros serem removidos."},{"id":"terra-terremoto","nome":"Terremoto","tipo":"Ataque","trad":"Terra","grau":4,"texto":"Área: Uma círculo no chão com raio de 20 metros centralizado em um ponto a longa distância Duração: 1 minuto O solo treme e se agita violentamente na área, que conta como um terreno difícil pela duração do feitiço. Quando você conjurar o feitiço, e ao final de cada rodada pela sua duração, cada criatura que está em pé na área deve fazer uma rolagem de desafio de Agilidade. Se fracassar, sofre 1d6 de dano e fica prostrada. Além disso, quando você conjurar o feitiço, e ao final de cada rodada pela sua duração, qualquer estrutura na área sofre 2d6 de dano. Qualquer estrutura destruída por esse dano desaba, causando 4d6+10 de dano a tudo que estiver dentro, ou debaixo, dela. Criaturas sobre a estrutura podem sofrer dano por queda quando ela desabar."},{"id":"terra-vincular-genio-da-terra","nome":"Vincular Gênio da Terra","tipo":"Utilitário","trad":"Terra","grau":5,"texto":"Alvo: Um cubo feito de terra ou pedra, com 2 metros de lado, com origem em um ponto a longa distância Duração: 1 minuto No final da rodada em que você conjura este feitiço, o alvo se transforma em um gênio da terra de Tamanho 2. Você não pode encerrar este feitiço voluntariamente. Quando o efeito termina, o gênio se desfaz, transformando o solo em seu espaço em terreno difícil. Quando o gênio surgir, faça uma rolagem de ataque de Vontade contra a Vontade dele. Em caso de sucesso, o gênio fica compelido enquanto o efeito durar; se fracassar, ele se torna hostil a você."},{"id":"teurgia-criar-simbolo-sagrado","nome":"Criar Símbolo Sagrado","tipo":"Utilitário","trad":"Teurgia","grau":0,"texto":"Duração: 1 minuto; veja o efeito Um símbolo sagrado brilhante aparece em sua mão e permanece pela duração do feitiço ou até que você o solte. O símbolo sagrado concede 1 dádiva em suas rolagens de ataque com feitiços de Teurgia."},{"id":"teurgia-denunciar","nome":"Denunciar","tipo":"Ataque","trad":"Teurgia","grau":0,"texto":"Alvo: Uma criatura a curta distância que possa vê-lo e ouvi-lo Você apresenta seu símbolo sagrado ao alvo. Faça uma rolagem de ataque de Vontade contra a Vontade do alvo. Com um sucesso, o alvo fica amedrontado por 1 rodada. Rolagem de Ataque 20+ O alvo também fica prostrado."},{"id":"teurgia-bencao","nome":"Benção","tipo":"Utilitário","trad":"Teurgia","grau":1,"texto":"Alvo: Qualquer quantidade de criaturas ao seu alcance Duração: 1 minuto Você toca cada alvo e concede sua bênção. Enquanto o efeito durar, o alvo faz rolagens de ataque e de desafio com 1 dádiva, e não pode ficar amedrontado."},{"id":"teurgia-solo-sagrado","nome":"Solo Sagrado","tipo":"Utilitário","trad":"Teurgia","grau":1,"texto":"Área: Um hemisfério com raio de 3 metros centralizado em um ponto no chão a curta distância Duração: Concentração, até 1 minuto; veja o efeito Uma cúpula transparente e imóvel cintila pela duração do feitiço. Nada fora da cúpula pode atravessá-la, e sua área interna não pode ser afetada pelos efeitos de feitiço algum. Criaturas e objetos dentro da cúpula estão escondidos de todos aqueles fora dela, exceto você. Uma criatura dentro da cúpula pode sair livremente mas, uma vez fora, não poderá retornar. O efeito termina imediatamente se uma criatura dentro da cúpula fizer um ataque."},{"id":"teurgia-repreensao","nome":"Repreensão","tipo":"Ataque","trad":"Teurgia","grau":1,"texto":"Área: Uma esfera com raio de 5 metros centrada em um ponto ao seu alcance Você apresenta seu símbolo sagrado, um trecho das escrituras ou alguma outra representação física de sua fé, e libera uma onda de poder sagrado que se espalha por toda a área. Cada demônio, diabo, fada, espírito e morto-vivo na área deve fazer uma rolagem de desafio de Vontade. Se fracassar, o alvo fica amedrontado por 1 minuto."},{"id":"teurgia-martelo-divino","nome":"Martelo Divino","tipo":"Ataque","trad":"Teurgia","grau":2,"texto":"Alvo: Um ponto no espaço a média distância Duração: 1 minuto Um martelo dourado brilhante aparece no alvo e paira sobre ele. Enquanto o efeito durar, você pode usar uma ação desencadeada no seu turno para mover o martelo em até 10 metros e atacar uma criatura que esteja a menos de 1 metro de distância dele. Faça uma rolagem de ataque de Vontade com 1 dádiva contra a Defesa do alvo. Com um sucesso, o alvo sofre 2d6 de dano. Rolagem de Ataque 20+ O alvo sofre 2d6 de dano extra."},{"id":"teurgia-revelacao","nome":"Revelação","tipo":"Utilitário","trad":"Teurgia","grau":2,"texto":"Alvo: Uma criatura ao seu alcance Duração: 1 minuto; veja o efeito Ao tocar no alvo, você concede a ele sete revelações, que duram enquanto o efeito estiver ativo ou até que ele gaste a última revelação. Quando o alvo faz uma rolagem de ataque ou desafio, ele pode gastar qualquer quantidade de revelações que ainda tiver. Para cada revelação que ele gastar, o alvo faz uma rolagem com 2 dádivas."},{"id":"teurgia-ajuda-divina","nome":"Ajuda Divina","tipo":"Utilitário","trad":"Teurgia","grau":3,"texto":"Alvo: Cada criatura escolhida por você a curta distância Duração: 1 hora Você alvo recebe um bônus de +15 em Vida pela duração do feitiço."},{"id":"teurgia-ira-divina","nome":"Ira Divina","tipo":"Ataque","trad":"Teurgia","grau":3,"texto":"Alvo: Um ponto no chão a média distância Um relâmpago atinge o alvo, causando 2d6+2 de dano a cada criatura dentro de 1d6 metros desse ponto. Uma criatura ferida dessa maneira deve fazer uma rolagem de desafio de Agilidade. Se fracassar, fica aturdida por 1 rodada; em caso de sucesso, sofre apenas metade do dano."},{"id":"teurgia-avatar","nome":"Avatar","tipo":"Utilitário","trad":"Teurgia","grau":4,"texto":"Duração: 1 minuto O poder divino flui para dentro de você. Enquanto o efeito durar, você sofre metade do dano de todas as fontes, faz rolagens de ataque com 1 dádiva e causa 2d6 de dano extra em ataques feitos com armas corpo a corpo."},{"id":"teurgia-fogo-celeste","nome":"Fogo Celeste","tipo":"Ataque","trad":"Teurgia","grau":5,"texto":"Área: Um cilindro vertical com 25 metros de altura e 5 metros de raio, centralizado em um ponto no chão a extrema distância As chamas se espalham pela área, causando 7d6 de dano a cada criatura dentro dela. Uma criatura que obtém sucesso em uma rolagem de Vontade sofre metade do dano. Qualquer criatura incapacitada por esse dano desaparece e é apagada do tecido da realidade."},{"id":"transformacao-forma-fluida","nome":"Forma Fluída","tipo":"Utilitário","trad":"Transformação","grau":0,"texto":"Duração: 1 minuto Enquanto o efeito durar, você pode se mover através de espaços ocupados por outras criaturas, independentemente do Tamanho delas."},{"id":"transformacao-mascara","nome":"Máscara","tipo":"Utilitário","trad":"Transformação","grau":0,"texto":"Duração: 1 hora; ver o efeito Você altera a aparência do seu corpo para que se pareça com outra pessoa pela duração do feitiço ou até perder a consciência. Você pode aumentar ou diminuir sua altura em até 30 centímetros, aumentar ou diminuir seu peso em até 25% ou fazer quaisquer outras alterações cosméticas que quiser. Nenhum dos seus atributos, características e demais habilidades muda, e você não pode assumir uma ancestralidade diferente."},{"id":"transformacao-forma-animal","nome":"Forma Animal","tipo":"Utilitário","trad":"Transformação","grau":1,"texto":"Duração: 1 minuto Você assume a forma de um animal médio , animal pequeno , ou animal minúsculo pela duração do feitiço. Se assumir a forma de um animal minúsculo, pode adquirir um dos seguintes traços: escalador, voador ou nadador. aterrissando com segurança."},{"id":"transformacao-revoada","nome":"Revoada","tipo":"Utilitário","trad":"Transformação","grau":1,"texto":"Você se desfaz em uma nuvem de estorninhos e voa até o dobro da sua Velocidade sem desencadear ataques livres; você pode se mover através de espaços ocupados por outras criaturas, independentemente do Tamanho delas. Ao final desse movimento, você retorna à sua forma normal. Desencadeada Você pode usar uma ação desencadeada para conjurar este feitiço quando sofrer dano. Neste caso, você sofre metade do dano do ataque que desencadeou a ação e se move até metade da sua Velocidade, conforme descrito acima."},{"id":"transformacao-salto-distante","nome":"Salto Distante","tipo":"Utilitário","trad":"Transformação","grau":1,"texto":"Duração: 1 minuto Enquanto o efeito durar, você ganha um bônus de +4 em Velocidade e pode usar uma ação para pular 3d6 metros,"},{"id":"transformacao-forma-animal-melhorada","nome":"Forma Animal Melhorada","tipo":"Utilitário","trad":"Transformação","grau":2,"texto":"Duração: 1 hora Você assume a forma de um animal grande , animal médio , animal pequeno , ou animal minúsculo e permanece nesta forma pela duração. Se assumir a forma de um animal pequeno ou minúsculo, você adquire um dos seguintes traços: escalador, voador ou nadador."},{"id":"transformacao-forma-de-objeto","nome":"Forma de Objeto","tipo":"Utilitário","trad":"Transformação","grau":2,"texto":"Duração: Concentração, até 8 horas Você assume a forma de um objeto do seu Tamanho ou menor pela duração do feitiço, tornando-se fisicamente indistinguível do objeto cuja forma assumiu. Você decide os detalhes da aparência exata da sua nova forma. Enquanto o efeito durar, você não pode falar e só pode usar ações para se concentrar neste feitiço. Entretanto, você percebe o ambiente ao seu redor usando seus sentidos normais. O efeito termina se você sofrer qualquer dano."},{"id":"transformacao-forma-enevoada","nome":"Forma Enevoada","tipo":"Utilitário","trad":"Transformação","grau":3,"texto":"Duração: Concentração, até 1 hora Você assume a forma de uma nuvem ou névoa do seu Tamanho pela duração do feitiço. Até o efeito terminar, você adquire os seguintes benefícios e desvantagens: • Você se torna imune a dano. • Você ignora os efeitos de rolagens de ataque contra sua Força ou que exigem uma rolagem de desafio de Força. • Você pode se mover através de aberturas largas o suficiente para permitir a passagem de ar, embora não possa se mover para espaços cheios de líquido — trate-os como objetos sólidos. • Você não cai. Você é imune às seguintes aflições: agarrado, imobilizado, lento e prostrado. • Você não pode falar, usar ações, lançar feitiços ou usar objetos. Ao final de cada rodada, quando estiver em uma área com vento, você é deslocado 2d6 metros na direção em que o vento sopra, e sofre uma penalidade cumulativa de –5 na sua Vida. A penalidade permanece até que você retorne à sua forma normal."},{"id":"transformacao-cura-rapida","nome":"Cura Rápida","tipo":"Utilitário","trad":"Transformação","grau":3,"texto":"Você deve se concentrar por 1 minuto enquanto conjura esse feitiço. Se mantiver sua concentração ininterruptamente, ao final daquele período você cura dano igual ao dobro da sua taxa de cura e remove de si mesmo as seguintes aflições: doente, fatigado e envenenado."},{"id":"transformacao-metalico","nome":"Metálico","tipo":"Utilitário","trad":"Transformação","grau":4,"texto":"Duração: 1 minuto Seu corpo se transforma em metal. Enquanto o efeito durar, sua Defesa se torna 20; você ganha um bônus de +10 em Vida; você fica imune às aflições adormecido, cego, surdo, doente, fatigado e envenenado; e você não pode ser movido contra a sua vontade. Você também sofre metade do dano causado por frio, fogo ou armas. Entretanto, você também fica lento, não consegue beber, comer ou nadar."},{"id":"transformacao-forma-animal-maior","nome":"Forma Animal Maior","tipo":"Utilitário","trad":"Transformação","grau":5,"texto":"Duração: 1 hora Você assume a forma de um animal enorme , animal grande , animal médio , animal pequeno , ou animal minúsculo pela duração do feitiço. Se assumir a forma de um animal médio, pequeno ou minúsculo, você adquire um dos seguintes traços: escalador, voador ou nadador."},{"id":"vida-cura-menor","nome":"Cura Menor","tipo":"Utilitário","trad":"Vida","grau":0,"texto":"Alvo: Uma criatura ao seu alcance Ao tocar o alvo, ele cura dano equivalente à metade de sua própria taxa de cura."},{"id":"vida-sentir-vida","nome":"Sentir Vida","tipo":"Utilitário","trad":"Vida","grau":0,"texto":"Área: Uma esfera com raio de 5 metros centralizada em um ponto dentro do seu espaço Duração: 1 minuto Você sente a localização de cada criatura na área. Tais criaturas não podem se esconder de você pela duração do feitiço."},{"id":"vida-cura","nome":"Cura","tipo":"Utilitário","trad":"Vida","grau":1,"texto":"Alvo: Uma criatura ao seu alcance Você toca o alvo e concede a ele um dos seguintes benefícios: • Remove uma das seguintes aflições do alvo: doente, fatigado, debilitado ou envenenado. • Remove 1 ponto de Insanidade do alvo. • Remove qualquer penalidade à Vida do alvo. • Cura uma quantidade de dano igual à metade da taxa de cura dele."},{"id":"vida-cura-leve","nome":"Cura Leve","tipo":"Utilitário","trad":"Vida","grau":1,"texto":"Alvo: Uma criatura ao seu alcance Ao tocar o alvo, ele cura dano equivalente à sua própria taxa de cura."},{"id":"vida-fonte-de-vida","nome":"Fonte de Vida","tipo":"Utilitário","trad":"Vida","grau":1,"texto":"Área: Uma esfera com raio de 2 metros centralizada em um ponto ao seu alcance Duração: 1 minuto Energias curativas se espalham pela área, acompanhando você pela duração do feitiço. Sempre que uma criatura viva dentro da área curar dano, ela cura uma quantidade adicional igual ao seu Poder."},{"id":"vida-cura-moderada","nome":"Cura Moderada","tipo":"Utilitário","trad":"Vida","grau":2,"texto":"Alvo: Uma criatura ao seu alcance Ao tocar o alvo, ele cura dano equivalente ao dobro da sua própria taxa de cura."},{"id":"vida-explosao-de-vitalidade","nome":"Explosão de Vitalidade","tipo":"Utilitário","trad":"Vida","grau":2,"texto":"Alvo: Até três criaturas vivas a curta distância O alvo cura dano igual à sua própria taxa de cura."},{"id":"vida-cura-maior","nome":"Cura Maior","tipo":"Utilitário","trad":"Vida","grau":3,"texto":"Alvo: Até três criaturas vivas ao seu alcance Você toca cada alvo e concede a cada um deles um dos seguintes benefícios — é possível escolher um benefício diferente para cada alvo: • Remove uma das seguintes aflições do alvo: doente, fatigado, debilitado ou envenenado. • Remove 1 ponto de Insanidade do alvo. • Remove qualquer penalidade à Vida do alvo. • O alvo cura dano igual à sua própria taxa de cura."},{"id":"vida-cura-superior","nome":"Cura Superior","tipo":"Utilitário","trad":"Vida","grau":3,"texto":"Alvo: Uma criatura ao seu alcance Ao tocar o alvo, o ele cura dano equivalente ao triplo da sua própria taxa de cura."},{"id":"vida-cura-total","nome":"Cura Total","tipo":"Utilitário","trad":"Vida","grau":4,"texto":"Alvo: Uma criatura ao seu alcance Você toca o alvo, curando todo seu dano."},{"id":"vida-ressuscitar","nome":"Ressuscitar","tipo":"Utilitário","trad":"Vida","grau":5,"texto":"Alvo: Uma criatura, morta há não mais do que 24 horas, ao seu alcance Você toca o alvo. Você deve se concentrar por 1 hora e, durante esse período, deve manter contato físico com o alvo. Se mantiver sua concentração ininterruptamente por 1 hora inteira, há uma possibilidade do alvo voltar da morte. Se a alma do alvo residir no Submundo, ela retorna ao seu corpo e ele volta à vida. O alvo recupera 1 ponto de dano e fica fatigado e debilitado até completar um descanso. Se a alma do alvo residir no Inferno, faça uma rolagem de desafio de Vontade com uma quantidade de reveses igual à Corrupção do alvo. Em caso de sucesso, você restaura a vida do alvo conforme descrito acima. Se fracassar, a alma está completamente perdida. Não é possível retorná-la ao seu corpo com outras conjurações deste feitiço. Sacrifício Você pode gastar uma conjuração deste feitiço para usar cura total ."}];
SDL.feiticosTrilha=[{"id":"sentir-magia","nome":"Sentir Magia","tipo":"Utilitário","trad":"Trilha","grau":0,"atr":"intelecto","origem":"Mágico","texto":"Área: Uma esfera com raio de 5 metros centralizada em um ponto dentro do seu espaço Você sabe se há efeitos mágicos em curso na área e de onde eles se originam."},{"id":"arma-enfeiticada","nome":"Arma Enfeitiçada","tipo":"Utilitário","trad":"Trilha","grau":0,"atr":"intelecto","origem":"Ata-Feitiços","texto":"Você toca em uma arma ao seu alcance e a imbui com poder mágico que dura 4 horas. Enquanto o feitiço estiver ativo, você ganha os seguintes benefícios com a arma: • A arma conta como seu implemento. • A arma concede 1 dádiva em rolagens de ataque feitas com ela. • Se a arma estiver a 1,5 km de distância, você pode usar uma ação para teletransportá-la diretamente para sua mão — ou para seus pés, caso suas mãos estejam ocupadas. • Desde que possua ao menos um fragmento da arma, você pode usar uma ação para tocá-la e remover todo o seu dano, mesmo que ela esteja completamente destruída. Sacrifício Você pode usar uma ação desencadeada para gastar a conjuração deste feitiço. Até o final da rodada, seus ataques com a arma causam dano extra igual ao seu Poder."},{"id":"fogo-bruxo","nome":"Fogo Bruxo","tipo":"Ataque","trad":"Trilha","grau":1,"atr":"intelecto","origem":"Bruxo","texto":"Alvo: Você Duração: Concentração, até 1 minuto Enquanto o feitiço durar, você se torna invisível, e uma bola de fogo verde surge centralizada em um ponto ao seu alcance. Quando o efeito termina, você se teletransporta para um espaço desocupado à sua escolha a até 1 metro da bola de fogo. Ao conjurar este feitiço — e novamente a cada vez que você usar uma ação para se concentrar nele — você pode mover a bola de fogo até 10 metros e atacar uma criatura a até 1 metro dela. Faça uma rolagem de ataque de Intelecto ou Vontade contra a Agilidade do alvo. Com um sucesso, o alvo sofre 2d6 de dano. Rolagem de Ataque 20+ O alvo sofre 1d6 de dano extra."},{"id":"exorcismo","nome":"Exorcismo","tipo":"Ataque","trad":"Trilha","grau":1,"atr":"vontade","origem":"Exorcista","texto":"Alvo: Uma criatura encantada, compelida, amedrontada ou possuída em curta distância. Se o alvo estiver encantado, compelido ou amedrontado, você remove essa aflição. Se estiver possuído, você deve se concentrar por 1 minuto, durante o qual o alvo deve permanecer dentro do alcance, e então fazer uma rolagem de ataque de Vontade contra a Vontade da entidade possessora. Em caso de sucesso, a possessão termina e a entidade aparece em um espaço desocupado em curta distância e fica aturdida por 1 rodada. Rolagem de Ataque 20+ A entidade fica atordoada por 1 rodada."},{"id":"comandar-mortos-vivos","nome":"Comandar Mortos-Vivos","tipo":"Ataque","trad":"Trilha","grau":1,"atr":"intelecto","origem":"Necromante","texto":"Alvo: Uma criatura morta-viva a curta distância. Duração: 1 minuto Faça uma rolagem de ataque de Intelecto contra a Vontade do alvo. Em caso de sucesso, o alvo fica compelido a obedecê-lo durante a duração do feitiço. Rolagem de Ataque 20+ Você recupera a capacidade de conjurar este feitiço."},{"id":"animar-objeto","nome":"Animar Objeto","tipo":"Utilitário","trad":"Trilha","grau":1,"atr":"intelecto","origem":"Tecnomante","texto":"Alvo: Um objeto de Tamanho 2 ou menor a curta distância. Duração: 1 minuto O alvo torna-se um construto compelido, do mesmo Tamanho, pela duração do feitiço. Se o alvo estiver afixado a uma superfície, sua velocidade será 0."},{"id":"templo-da-fe","nome":"Templo da Fé","tipo":"Utilitário","trad":"Trilha","grau":0,"atr":"intelecto","origem":"Templário","texto":"Área: Uma esfera com raio de 5 metros centralizada em um ponto ao seu alcance. Se o ponto central for um ídolo, santuário ou altar relacionado à sua religião, o raio aumenta para 10 metros. Duração: 1 minuto, ou até você sair da área Energia sagrada permeia a área por toda a duração do feitiço. Quando uma criatura vinda de fora entra nessa área, você pode usar uma ação desencadeada para se mover até o máximo da sua Velocidade em direção a ela e atacá-la com uma arma. Em caso de sucesso, o criatura também fica imobilizada por 1 rodada."},{"id":"forma-de-sombra","nome":"Forma de Sombra","tipo":"Utilitário","trad":"Trilha","grau":1,"atr":"intelecto","origem":"Tenebrista","texto":"Duração: 1 minuto Você assume uma aparência sombria e indiscernível pela duração do efeito, obtendo os seguintes benefícios. • Criaturas que atacam sua Defesa ou Agilidade fazem a rolagem de ataque com 1 revés e, em caso de fracasso, você pode usar uma ação desencadeada para se mover até sua Velocidade. Este movimento não desencadeia ataques livres. • Você se torna invisível enquanto estiver em áreas obscurecidas por sombras ou na escuridão. • Além disso, você pode se mover por espaços ocupados por outras criaturas."}];
SDL.conjuracoes={"0": [1], "1": [2, 1], "2": [3, 2, 1], "3": [4, 2, 1, 1], "4": [5, 2, 2, 1, 1], "5": [6, 3, 2, 2, 1, 1], "6": [7, 3, 2, 2, 2, 1, 1], "7": [8, 3, 2, 2, 2, 1, 1, 1], "8": [9, 3, 3, 2, 2, 2, 1, 1, 1], "9": [10, 3, 3, 3, 2, 2, 1, 1, 1, 1], "10": [11, 3, 3, 3, 3, 2, 1, 1, 1, 1, 1]};
SDL.religioes=[["Culto do Novo Deus", ["Celestial", "Vida", "Teurgia"]], ["Ancestrais Anões", ["Batalha", "Terra", "Vida"]], ["Fé Antiga", ["Vida", "Natureza", "Primal"]], ["Bruxaria", ["Maldição", "Encantamento", "Vida"]]];
SDL.talentosEscolha={"sagaz":[{"n":"Punhalada pelas Costas","t":"Uma vez por rodada, quando você ataca com uma arma básica ou rápida, e faz a rolagem de ataque com pelo menos 1 dádiva, o ataque causa 1d6 de dano extra. Se você escolher este talento uma segunda vez, o dano extra aumenta para 2d6."},{"n":"Magia","t":"Aumente seu Poder em 1 e descubra uma tradição. Em seguida, faça duas escolhas. Para cada escolha, você descobre outra tradição ou aprende um feitiço de uma tradição que já descobriu. Se escolher este talento uma segunda vez, aumente seu Poder em 1 e descubra uma tradição ou aprenda um feitiço."},{"n":"Escaramuça","t":"Use uma ação para mover-se até metade da sua Velocidade. Este movimento não desencadeia ataques livres. Durante o movimento, você pode fazer um ataque. Você faz a rolagem de ataque com 1 revés, porém o ataque causa 1d6 de dano extra. Se escolher este talento uma segunda vez, você pode se mover até o total de sua Velocidade, e não apenas metade dela."},{"n":"Subterfúgio","t":"Você pode usar uma ação para fazer uma rolagem de ataque de Intelecto contra o Intelecto de uma criatura que esteja a curta distância e que possa ouvir e entender o que você diz. Com um sucesso, o alvo fica fascinado por 1 rodada ou até que você o ataque. Se fracassar, o alvo se torna imune ao seu Subterfúgio até completar um descanso. Se escolher este talento uma segunda vez, você faz a rolagem de ataque com 1 dádiva e pode afetar uma criatura que não entende o que você diz."},{"n":"Ameaças","t":"Você pode usar uma ação ou uma ação desencadeada no seu turno para fazer uma rolagem de ataque de Intelecto contra a Vontade de um alvo que esteja a curta distância e que possa ouvi-lo e vê-lo. Com um sucesso, o alvo fica amedrontado por 1 rodada. Se fracassar, o alvo se torna imune às suas Ameaças até completar um descanso. Se escolher este talento novamente, seus ataques com armas causarão 1d6 de dano extra a todos os alvos Amedrontados."}],"gatuno":[{"n":"Escapista","t":"Quando alguém o agarrar, você pode usar uma ação desencadeada para escapar. Quando estiver preso com amarras ou algemas, você pode usar uma ação para tentar escapar. Você deve se concentrar por 1 minuto. Ao final desse período, faça uma rolagem de desafio de Agilidade. Com um sucesso, você se livra das amarras. Se fracassar, você fica amarrado firmemente e assim permanece até ser libertado."},{"n":"Escondido nas Sombras","t":"Você pode tentar se esconder quando estiver em uma área obscurecida pelo menos parcialmente por sombras, mesmo se estiver sendo observado."},{"n":"Sentidos Aguçados","t":"Você faz todas as rolagens de Percepção com 1 dádiva."},{"n":"Movimento Silencioso","t":"Você faz rolagens de desafio para se esgueirar com 2 dádivas."},{"n":"Abrir Fechaduras","t":"Se usar gazuas para abrir uma fechadura, você pode usar uma ação para abrir uma fechadura ao seu alcance. Se o Mestre pedir uma rolagem de desafio, você recebe 1 dádiva."},{"n":"Punga","t":"Você pode usar uma ação, ou uma ação desencadeada no seu turno, para pegar um objeto de uma criatura ao seu alcance. O objeto roubado deve ser algo que você possa segurar em uma mão e tem de estar em algum lugar do corpo da criatura — porém não segurado em suas mãos (ou em um apêndice similar). Se puder ver o objeto, você pode pegá-lo. Se você não puder ver com clareza — por exemplo, se estiver dentro de um bolso ou mochila —, o MJ determina qual item foi levado."},{"n":"Escalar Paredes","t":"Você ignora os efeitos de terrenos difíceis ao escalar e faz rolagens de desafio de escalada com 1 dádiva."},{"n":"Detectar Armadilha","t":"Quando procura por armadilhas ou tenta resistir aos seus efeitos, você faz a rolagem de desafio com 1 dádiva."}],"lutador":[{"n":"Luta com Duas Armas","t":"Quando ataca com duas armas, você reduz a quantidade de reveses do ataque em 2."},{"n":"Ataque com o Cabo","t":"Quando ataca com uma arma de haste ou um cajado, você pode usar uma ação desencadeada para atacar com a outra ponta da arma. Faça a rolagem de ataque com 1 revés; o ataque causa 1d6 de dano."},{"n":"Ataque Poderoso","t":"Ao atacar com uma arma pesada, você pode fazer a rolagem de ataque com 1 revés para causar 2d6 de dano extra."},{"n":"Ataque Preciso","t":"Quando ataca com uma arma rápida, você pode fazer a rolagem de ataque contra a Agilidade do alvo em vez da Defesa."},{"n":"Pancada com o Escudo","t":"Quando obtém sucesso em uma rolagem de ataque feita com um escudo, você golpeia o alvo e faz rolagens de ataque contra o mesmo alvo com 2 dádivas até o final da próxima rodada."},{"n":"Recarga Rápida","t":"Você pode usar uma ação desencadeada no seu turno para recarregar uma arma que tenha a propriedade de recarga."},{"n":"Tiro Rápido","t":"Quando você faz um ataque com uma arma de combate à distância que não tem propriedade de recarga, você pode usar uma ação desencadeada para atacar com a mesma arma. Você faz a segunda rolagem de ataque com 1 revés."}]};
